parameters.jsCode:
// Reached either straight from `Called by Master Router` (outreach) or from
// `Is New Message?`. In the second case the item we are handed is the dedupe
// guard's HTTP response, not the webhook body -- an HTTP node's output REPLACES
// the item -- so reach back to the webhook node for the real payload.
let item = $input.first().json;
if (!item.lead && !item.body && !item.payload) {
  try { item = $('WAHA Webhook (POST)').first().json; } catch (e) { /* outreach path */ }
}

// ---- TENANT (2 Sep 2026) --------------------------------------------------
// Both entry points converge on this node, so this is where the dealership is
// settled once and becomes a value every downstream write carries explicitly.
// Writing without it means service_role (BYPASSRLS, no auth.uid()) lets the
// column default file the row under whichever tenant holds
// is_unattributed_default -- i.e. under dealership one, whoever actually sent
// the message.
//   webhook path  -> `Resolve Tenant` already derived it from the WAHA session,
//                    and REFUSED THE WHOLE RUN if that session was not on the
//                    allowlist, so by the time we are reached on this path the
//                    dealership is already settled. There is no second guess to
//                    make and none is made.
//   outreach path -> the Master Router hands it to us on the lead object.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);
//
// 3 Sep 2026: THE TWO ENTRY POINTS NOW GET DIFFERENT TREATMENT, ON PURPOSE.
// The old code ran one chain for both and ended it with "...and if none of that
// worked and exactly one dealership is configured, use that one". On the public
// webhook path that last clause was a hole: `Resolve Tenant` could refuse to
// identify the dealership and this node would quietly supply dealership one
// anyway. Whatever `Resolve Tenant` refuses must stay refused, so the webhook
// branch below has NO fallback of any kind. The outreach branch keeps the old
// chain unchanged -- it is reached only from `Called by Master Router`, i.e.
// from inside n8n's own trust boundary, and the Router has already resolved the
// dealership from a verified JWT or from the WAHA session.
let TENANT = '';
if (item.lead) {
  // OUTREACH (internal caller). Unchanged.
  TENANT = String(item.lead.tenant_id || '');
  if (!NEXUS_UUID.test(TENANT) && nexusKeys.length === 1) TENANT = String(nexusMap[nexusKeys[0]] || '');
} else {
  // WEBHOOK. The ONLY acceptable source is `Resolve Tenant`, which refuses
  // unless the WAHA session is on the allowlist. If that node has been disabled
  // as an emergency rollback this evaluates to null, the writes below omit
  // tenant_id, and the column default applies -- i.e. exactly the pre-patch
  // behaviour, which is what makes disabling it a safe rollback.
  try { TENANT = String(($('Resolve Tenant').first().json || {}).tenant_id || ''); } catch (e) { TENANT = ''; }
}
if (!NEXUS_UUID.test(TENANT)) TENANT = null;

if (item.lead) {
  const lead = item.lead;
  const interest = lead.vehicle_interest || lead.vehicleInterest || lead.message || 'a vehicle';
  let chatId = String(lead.phone || lead.whatsapp || '').trim();
  if (!chatId) return [];
  if (!chatId.includes('@')) chatId = chatId.replace(/[^0-9]/g, '') + '@c.us';
  return [{ json: {
    message: 'INITIAL_OUTREACH: Lead name: ' + (lead.name || 'there') + ', interested in: ' + interest + '. Send them a warm, personalised WhatsApp welcome message introducing the NEXUS OS dealership and asking how you can help.',
    sender: chatId,
    lead_email: lead.email || null,
    tenant_id: TENANT,
    direction: 'outbound',
    is_voice: false,
    // Outreach is not a WAHA delivery. Give it a unique id so the idempotency
    // guard downstream always lets it through.
    message_id: 'outreach:' + Date.now() + '-' + Math.random().toString(36).slice(2, 10)
  } }];
}

const body = item.body || item;
const payload = body.payload || {};

const event = String(body.event || '');
if (event && event !== 'message') return [];

// Never reply to our own messages -> this is what caused the infinite loop
if (payload.fromMe === true) return [];

// Drop groups, status broadcasts and newsletters.
// NOTE: '@lid' is NOT filtered - WhatsApp now uses LID addressing for real
// 1:1 customer chats, so blocking it silently drops genuine messages.
const from = String(payload.from || '');
if (!from || from.endsWith('@g.us') || from.startsWith('status@') || from.endsWith('@newsletter')) return [];

// A customer sending their Emirates ID sends an IMAGE with no caption. The old
// code did `if (!text) return []` and silently dropped it - the KYC workflow was
// never reachable from WhatsApp at all. Detect media and carry it forward.
const text = typeof payload.body === 'string' ? payload.body.trim() : '';
const media = payload.media || {};
const isImage = payload.hasMedia === true && String(media.mimetype || '').startsWith('image/');

// WAHA hands back its own file URL as localhost:3000 - that is localhost *inside
// the WAHA container*. n8n must fetch it over the docker network instead.
const documentUrl = isImage
  ? String(media.url || '').replace('http://localhost:3000', 'http://waha:3000')
  : null;

// 30 Aug 2026: VOICE NOTES (PTT). Before this, a voice note had no text and a
// non-image mimetype, so `if (!text && !isImage) return []` below dropped the
// execution HERE, at node 6 of ~16. Nothing downstream ever ran, which is why
// customers who spoke instead of typing got total silence.
//
// Branch on the EXISTENCE of _data.Message.audioMessage, not on Info.MediaType:
// MediaType is 'ptt' for a held-mic recording but 'audio' for a forwarded audio
// file, and some GOWS builds omit it entirely. audioMessage is present for both.
const audioMsg = (payload._data && payload._data.Message && payload._data.Message.audioMessage) || null;
const isVoice = !!audioMsg;
const audioUrl = isVoice
  ? String(media.url || '').replace('http://localhost:3000', 'http://waha:3000')
  : null;
const audioSeconds = isVoice ? Number(audioMsg.seconds || 0) : 0;
const audioMime = isVoice ? String(media.mimetype || audioMsg.mimetype || 'audio/ogg; codecs=opus') : null;

if (!text && !isImage && !isVoice) return [];

// WhatsApp now addresses many 1:1 chats by LID (e.g. 158510264357112@lid), which
// carries NO phone number -- matching a lead on its digits is impossible. The real
// number is in _data.Info.SenderAlt. Keep `sender` as the chat id (replies must go
// back to it) and expose the true number separately for lead matching.
const info = (payload._data && payload._data.Info) || {};
const alt = String(info.SenderAlt || '');
const senderPhone = (alt.includes('@') ? alt.split('@')[0] : alt) ||
                    (from.endsWith('@lid') ? '' : from.split('@')[0]);

// WAHA has delivered the same message three times in one second, repeatedly.
// `payload.id` is the WhatsApp message id and is stable across those duplicates,
// so it is what the idempotency guard downstream claims. Fall back to
// sender+timestamp when WAHA omits it; empty means the guard cannot key on
// anything and will let the message through.
const messageId = String(payload.id || (payload.timestamp ? from + ':' + payload.timestamp : ''));

// The image placeholder must NOT be reused for audio: it contains the word
// 'document', which is in Reply Eligibility's keyword allowlist, and
// `New Lead Worth Scoring?` string-compares against it. Either way this value is
// replaced by the transcript before Resolve Lead Identity emits it.
const placeholder = isImage ? '[Customer sent a document image]' : '[Customer sent a voice note]';

return [{ json: {
  message_id: messageId,
  message: text || placeholder,
  is_document: isImage,
  document_url: documentUrl,
  is_voice: isVoice,
  audio_url: audioUrl,
  audio_seconds: audioSeconds,
  audio_mime: audioMime,
  sender: from,
  sender_phone: senderPhone,
  push_name: info.PushName || null,
  lead_email: null,
  tenant_id: TENANT,
  direction: 'inbound'
} }];

// Resolve the WhatsApp chat id back to a real lead so every log row is keyed
// on the lead's EMAIL, not on a raw chat id. Without this the silence detector
// (Phase 6) can never join communication_logs back to the leads table.
//
// Match on sender_phone (the true number pulled from Info.SenderAlt), NOT on the
// chat id -- a LID chat id has no phone digits in it at all.
const ex = $('Extract Message & Sender').first().json;

// 30 Aug 2026: VOICE NOTES. A voice note's words only exist after transcription,
// which runs between `Extract Message & Sender` and this node. Prefer that
// transcript here and nowhere else: EVERY downstream consumer of the customer's
// words reads `message` off THIS node --
//   Reply Eligibility (keyword allowlist), Model Ladder (`message: ctx.message`,
//   which overrides whatever the previous node passed), the AI agent's prompt
//   expression, Skip Duplicate Outreach, New Lead Worth Scoring?,
//   Shape Lead For Router, Log Incoming Message.
// Substituting once, here, is what makes a voice note behave exactly like text.
let voice = null;
try {
  const mt = $('Merge Voice Transcript');
  if (mt && (mt.isExecuted === undefined || mt.isExecuted)) voice = mt.first().json || null;
} catch (e) { voice = null; }
const digits = String(ex.sender_phone || ex.sender || '').replace(/[^0-9]/g, '');
const last9 = digits.slice(-9);

// A lead row is what makes `matched_lead` true, and `matched_lead` is what makes the bot
// answer someone unconditionally. So a wrong number that got written into `leads` by
// mistake would be answered forever. Marking it DISQUALIFIED in the dashboard is the
// reversible way to take it back out of the allowlist -- nothing is deleted.
//
// 2 Sep 2026 TENANCY: `Fetch All Leads` is now filtered to this message's tenant
// server-side. This second filter is belt and braces, and it is the one that
// still holds if someone widens that node again: a phone tail is only nine
// digits, and matching it against ANOTHER dealership's lead would answer their
// customer by name out of this dealership's WhatsApp number.
const leads = $input.all().map(i => i.json)
  .filter(l => l && l.phone && String(l.status || '').toUpperCase() !== 'DISQUALIFIED')
  .filter(l => !ex.tenant_id || !l.tenant_id || String(l.tenant_id) === String(ex.tenant_id));
let match = null;
if (last9.length === 9) {
  match = leads.find(l => String(l.phone).replace(/[^0-9]/g, '').slice(-9) === last9) || null;
}

return [{ json: {
  message: (voice && voice.message) ? voice.message : ex.message,
  is_document: ex.is_document || false,
  is_voice: !!voice,
  voice_transcribed: voice ? voice.voice_transcribed === true : false,
  voice_transcript: voice ? String(voice.voice_transcript || '') : '',
  voice_language: voice ? (voice.voice_language || null) : null,
  voice_seconds: voice ? Number(voice.voice_seconds || 0) : 0,
  voice_drop_reason: voice ? String(voice.voice_drop_reason || '') : '',
  document_url: ex.document_url || null,
  sender: ex.sender,
  sender_phone: ex.sender_phone || null,
  push_name: ex.push_name || null,
  direction: ex.direction,
  tenant_id: ex.tenant_id || null,
  lead_email: ex.lead_email || (match ? match.email : null),
  lead_name: match ? match.name : (ex.push_name || null),
  matched_lead: !!match
} }];

// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The previous ladder had a PAID gemini tier plus
// two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free is
// 404 free-tier-discontinued), which is why all 4 tiers failed on live traffic.
//
// 29 Aug 2026: REMOVED tier 1, 'nvidia/nemotron-3-ultra-550b-a55b:free'. It failed
// on BOTH agents inside the same real run -- exec 6251 here (46.5s wasted) and
// exec 6253 in the Master Router (45.8s) -- with 'Cannot read properties of
// undefined (reading \'message\')'. The ladder escalated correctly each time, so
// this was never a ladder bug: the model is dead, and every inbound message was
// paying ~45s for it before getting a real answer. That run took 87s end to end,
// and at 5 production slots this latency is a direct contributor to concurrency
// exhaustion -- the box hit 6/5 active with a growing queue the same morning.
//
// 30 Aug 2026: groqModel changed from 'llama-3.3-70b-versatile' to
// 'openai/gpt-oss-120b' on every tier. Groq SHUT DOWN llama-3.3-70b-versatile
// for free and developer tiers on 16 Aug 2026 -- their deprecations page names
// openai/gpt-oss-120b as the replacement, their models page now marks the old
// id Enterprise/Contact-Sales, and it has no row at all in the free-tier
// rate-limit table. Because Groq is only the FALLBACK model, it had never
// fired in production, so nothing had surfaced this: the slot would have
// failed for the first time on the day the primary was already down. The
// replacement is production-tier (not preview), free-tier callable, and
// supports OpenAI-style tool calling, which the ladder requires.
// Free-tier ceiling to remember: 30 RPM / 1K RPD / 8K TPM / 200K TPD -- the
// 8K tokens-per-minute limit binds well before the request limit does.
const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',                groqModel: GROQ_FALLBACK }
];
// 'Log Incoming Message' is a Supabase insert that returns an EMPTY body, so
// $input here carries no message and the Agent failed with "No prompt specified"
// on every tier -- which looked like a model outage but never was. Pull the
// conversation context straight from 'Resolve Lead Identity' and re-attach it on
// every retry, so the prompt survives the ladder loop.
let ctx = {};
try { ctx = $('Resolve Lead Identity').first().json || {}; } catch (e) { ctx = {}; }

const prev = $input.first().json;
const attempt = Number(prev.__attempt ?? -1) + 1;
if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed. Tried: ' + TIERS.map(t=>t.orModel).join(', '));
}
if (!ctx.message) {
  throw new Error('No message found on Resolve Lead Identity output - cannot prompt the agent.');
}
return [{ json: { ...ctx, ...prev, message: ctx.message, __attempt: attempt, orModel: TIERS[attempt].orModel, groqModel: TIERS[attempt].groqModel } }];

// Quality gate before anything reaches a real customer on WhatsApp.
//
// 31 Aug 2026 -- REWRITTEN after the worst leak this system has produced.
// A customer asked "can you do better for a cash payment?" and received the
// model's entire internal deliberation, roughly 3,000 characters of it,
// including the literal line "price_aed 585,000, cost_aed 530,000" -- what the
// dealership PAID for the car -- plus the 8% ceiling, the floor arithmetic, and
// long verbatim quotes of the negotiation rules themselves.
//
// The old gate matched a whitelist of opening phrases anchored with ^ :
//   /^(the user|okay|we need to|i should|let's see|analysis|reasoning)\b/
// The leak began "We have inventory data:" -- not on the list -- so it passed
// untouched. A whitelist of first words cannot work: there is an unbounded
// number of ways a model can start thinking out loud, and being wrong once
// costs the negotiation and the cost price.
//
// This gate is now DENY-based and looks at the WHOLE text, not the first word.
// Three independent tests, any one of which blocks:
//   1. Internal vocabulary that must never leave the building.
//   2. Meta-language -- the model talking ABOUT the reply instead of writing it.
//   3. A discount percentage, which the rules forbid quoting in any form.
// Blocking is deliberately biased toward false positives: a customer who gets
// one holding sentence has a mildly worse minute, while a customer who learns
// cost_aed has the whole negotiation.
const prev = $input.first().json;
let text = String(prev.output ?? '').trim();

// Explicit reasoning wrappers some models emit.
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '')
           .replace(/<reasoning>[\s\S]*?<\/reasoning>/gi, '')
           .replace(/<\|?(?:begin|start)_of_thought\|?>[\s\S]*?<\|?(?:end)_of_thought\|?>/gi, '')
           .trim();

// WhatsApp renders none of markdown. Convert what the model still slips through.
text = text.replace(/^\s*\|.*\|\s*$/gm, '')          // table rows
           .replace(/^\s*[-: |]{6,}\s*$/gm, '')      // table separators
           .replace(/\*\*(.+?)\*\*/g, '*$1*')        // **bold** -> *bold*
           .replace(/^#{1,6}\s*/gm, '')              // headings
           .replace(/\n{3,}/g, '\n\n')
           .trim();

const reasons = [];

// -- 1. Internal vocabulary -------------------------------------------------
// Database column names, tool names, workflow nouns and the headings of the
// agent's own rulebook. None of these has any business in a sales message, so
// a single occurrence anywhere is disqualifying. cost_aed leads the list
// because it is the one that costs real money.
const INTERNAL = [
  'cost_aed', 'price_aed', 'days_in_stock', 'ai_score', 'budget_aed',
  'lead_email', 'assigned_to', 'whatsapp.lead', 'vehicle_interest',
  'finance_calculator', 'search_inventory', 'search_policy', 'fromai',
  'system_note', 'initial_outreach', 'delivery report', 'audit_log',
  'communication_logs', 'system prompt', 'system message', 'guardrail',
  'negotiation guardrails', 'cash versus finance', 'no recaps',
  'whatsapp formatting', 'tool call', 'inventory data', 'inventory price'
];
const lower = text.toLowerCase();
for (const t of INTERNAL) {
  if (lower.includes(t)) { reasons.push('internal term: ' + t); break; }
}

// 31 Aug 2026: a leak reached a real customer reading
//   "We have inventory price 585,000. Customer credit score 600.
//    Finance calculator returned indicative APR 8.2-9.64"
// and NOTHING above caught it, because the list stores 'finance_calculator'
// with an underscore and the model wrote 'Finance calculator' with a space.
// A deny-list that only matches one spelling of a token is not a deny-list.
// So: match a second time against text whose separators are normalised, using
// only the tokens whose spaced form is still unambiguous in a sales message.
// ('search inventory' and 'assigned to' are deliberately NOT here -- a real
// salesperson could plausibly write both.)
// NOTE: 'price aed' / 'cost aed' are deliberately absent. Normalising
// price_aed to 'price aed' also matches the perfectly good sales line
// "Price AED 585,000." -- the test suite caught that regression. Column
// names built on _aed are handled by COLUMN_RE below, which accepts an
// underscore or a hyphen but never a space.
const INTERNAL_NORM = [
  'days in stock', 'ai score', 'lead email', 'vehicle interest',
  'finance calculator', 'system note', 'initial outreach', 'audit log',
  'communication logs', 'inventory price', 'inventory data',
  'inventory row', 'inventory record'
];
const COLUMN_RE = [
  /\b(?:cost|price|budget|value|margin)[_-]aed\b/i,
  /\bai[_-]score\b/i, /\bdays[_-]in[_-]stock\b/i,
  /\blead[_-]email\b/i, /\bassigned[_-]to\b/i, /\bvehicle[_-]interest\b/i,
  /\bgross[_-]margin\b/i, /\bnet[_-]margin\b/i, /\bholding[_-]cost\b/i
];
for (const re of COLUMN_RE) {
  if (re.test(text)) { reasons.push('column name: ' + re.source.slice(0, 32)); break; }
}
const norm = lower.replace(/[_\-]+/g, ' ').replace(/\s+/g, ' ');
for (const t of INTERNAL_NORM) {
  if (norm.includes(t)) { reasons.push('internal term (normalised): ' + t); break; }
}

// -- 1c. Structural internal identifiers -------------------------------------
// 02 Sep 2026. The deny-list above enumerates the columns we knew about. A
// live probe of the schema found eleven more that sailed straight through:
// vehicle_value_aed, loan_payoff_aed, equity_aed, finance_tier, credit_score,
// response_time_minutes, bitrix_lead_id, confidence_score, storage_path,
// apr_source, ltv_policy_source -- plus the view name v_inventory_sales.
// Enumerating columns is a losing race against a schema that keeps growing.
// The structural fact is stronger than any list: snake_case is a machine
// spelling. No human writes "your credit_score is 900" to a customer on
// WhatsApp, in any language this dealership sells in. So block the SHAPE.
// Emails, URLs and filenames are stripped first -- those legitimately carry
// underscores and must not trip the rule.
const deIdentified = text
  .replace(/\b[\w.+-]+@[\w.-]+\.\w{2,}\b/g, ' ')
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(/\b[\w-]+\.(?:jpe?g|png|gif|pdf|docx?|xlsx?|csv|txt)\b/gi, ' ');
const SNAKE_RE = /\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b/i;
const snakeHit = deIdentified.match(SNAKE_RE);
if (snakeHit) reasons.push('internal identifier (snake_case): ' + snakeHit[0].slice(0, 40));

// -- 1d. Internal commercial language ----------------------------------------
// The cost/margin test in 3b needs a money figure nearby. These phrasings carry
// no number and so escaped it, while still handing the customer the inside of
// the negotiation: "Our margin here is healthy", "I am allowed up to eight
// percent", "I cannot go below our floor". Margin, floor, ceiling and discount
// authority are internal concepts; a customer hears only a price.
// Scoped tightly with a possessive so ordinary car words survive: "showroom
// floor", "floor mats", "under the ceiling lining" and "cost of ownership"
// must all still send. (An unpossessed "under the ceiling" rule was tried and
// removed: it blocked a legitimate sunroof/headroom reply in the test suite.)
const INTERNAL_COMMERCIAL = [
  /\b(?:our|my|the)\s+(?:gross\s+|net\s+|profit\s+)?margin\b/i,
  /\b(?:our|my)\s+(?:price\s+)?(?:floor|ceiling)\b/i,
  /\b(?:below|under|beneath)\s+(?:our|my)\s+(?:floor|ceiling|cost|minimum)\b/i,
  /\bmax(?:imum)?\s+discount\b/i,
  /\bdiscount\s+(?:ceiling|ladder|authority|band|cap)\b/i,
  /\bi(?:'m|’m| am)\s+(?:allowed|authoris\w+|authoriz\w+|permitted)\s+(?:to\s+|up\s+to\s+)/i,
  /\bwhat\s+we\s+paid\b/i
];
for (const re of INTERNAL_COMMERCIAL) {
  if (re.test(text)) { reasons.push('internal commercial language: ' + re.source.slice(0, 40)); break; }
}

// -- 2. Meta-language -------------------------------------------------------
// The model narrating its own decision rather than talking to the customer.
// Phrases chosen to be things a salesperson would never write to a buyer.
// Note what is deliberately NOT here: "we can offer", "we can do" and similar
// are exactly how a real offer is phrased, so they must stay allowed.
const META = [
  /\bthe customer (?:asks|asked|is asking|wants|says)\b/i,
  /\bthe user\b/i,
  /\bwe (?:need to|must not|must ensure|should (?:not )?(?:say|offer|reveal|mention))\b/i,
  /\b(?:the|per the|according to the) (?:rule|rules|guideline|guidelines|policy states)\b/i,
  /\bthus we\b/i, /\bso we (?:need|must|can(?:not)?)\b/i,
  /\blet'?s (?:see|think|say)\b/i,
  /\bmust not (?:reveal|quote|say|mention)\b/i,
  /\bis (?:prohibited|disqualifying|forbidden)\b/i,
  /\bthat'?s okay\b/i, /\bbut we (?:need|must|haven'?t|don'?t)\b/i,
  /^(?:okay|alright)[,.]?\s+(?:the|so|we)\b/i,
  /\banalysis\s*:/i, /\breasoning\s*:/i,
  // 31 Aug 2026 -- added after the leak quoted above got through.
  // Talking ABOUT the customer in the third person. A reply written TO them
  // says "your credit score"; only a narration says "customer credit score".
  /\bcustomer(?:'s)?\s+(?:credit score|credit band|score|budget|email|phone number|intent|profile|message|reply)\b/i,
  // Naming the thing that produced a number instead of just giving the number.
  /\b(?:calculator|tool|search|lookup|query|system|api)\s+returned\b/i,
  /\breturned\s+(?:indicative|the following|a value|apr|results?)\b/i,
  // Opening by reciting retrieved data.
  /^\s*we have\s+(?:inventory|stock data|the data|data)\b/i
];
for (const re of META) {
  if (re.test(text)) { reasons.push('meta-language: ' + re.source.slice(0, 40)); break; }
}

// -- 3. Discount percentages ------------------------------------------------
// "NEVER write the discount percentage to the customer" -- quote money only.
// An APR is a legitimate percentage and must survive, so the test requires a
// discount word near the number rather than blocking every % sign.
const PCT_NEAR_DISCOUNT =
  /(\d{1,2}(?:\.\d+)?\s*%[^.\n]{0,60}\b(?:discount|off|off the list|reduction|below list)\b)|(\b(?:discount|off the list|reduction)\b[^.\n]{0,60}\d{1,2}(?:\.\d+)?\s*%)/i;
if (PCT_NEAR_DISCOUNT.test(text)) reasons.push('discount percentage quoted');
// 02 Sep 2026: the numeric test above only sees digits. "eight percent off"
// is the same disclosure written in words, so mirror it for spelled numbers.
const WORDNUM = '(?:one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty)';
const PCT_WORD_NEAR_DISCOUNT = new RegExp(
  '\\b' + WORDNUM + '\\s*(?:%|per\\s?cent|percent)\\b[^.\\n]{0,60}\\b(?:discount|off|below list|reduction)\\b' +
  '|\\b(?:discount|off the list|reduction)\\b[^.\\n]{0,60}\\b' + WORDNUM + '\\s*(?:%|per\\s?cent|percent)\\b', 'i');
if (PCT_WORD_NEAR_DISCOUNT.test(text)) reasons.push('discount percentage quoted (in words)');

// -- 3b. Cost and margin talk, however it is phrased -------------------------
// The token deny-list above catches the literal column names. It does NOT catch
// a model that paraphrases: "our internal acquisition cost is AED 530,000"
// contains no banned token and would have passed. Layer 1 now keeps these
// numbers out of the model's context entirely (the agent reads
// v_inventory_sales, which has no cost or margin columns), but this gate must
// still hold if that boundary is ever widened by accident.
// A money figure NEAR any cost/margin word is the signal -- not the word alone,
// because "at no cost to you" and "cost of ownership" are things a salesperson
// legitimately says.
const MONEY = /(?:aed|dhs?|د\.إ)\s?[\d,]{4,}|[\d,]{5,}\s?(?:aed|dhs?)/i;
const COST_WORD = /\b(?:acquisition cost|cost price|our cost|internal cost|we paid|we bought|purchase(?:d)? (?:it|the car|this) for|gross margin|net margin|our margin|markup|mark-up|our profit|profit margin|holding cost|commission)\b/i;
if (MONEY.test(text) && COST_WORD.test(text)) reasons.push('money figure next to a cost/margin word');

// -- 4. Shape ---------------------------------------------------------------
// A WhatsApp sales reply is short. Something this long is almost always the
// model thinking rather than answering, and the length itself is the tell.
if (text.length > 1500) reasons.push('too long for a WhatsApp reply: ' + text.length + ' chars');
if (text.length < 12)   reasons.push('too short / empty');

// -- 5. OUTBOUND FINANCE GATE (system Layer 4) ------------------------------
// 31 Aug 2026. A live customer was told "the indicative monthly payment over
// 60 months (with salary transfer) works out to roughly AED 11,200 per month".
// finance_calculator was never called. The model amortised the FULL AED 585,000
// -- 100% financing, which no UAE bank writes. The true figure was ~AED 7,800.
// Nothing caught it: no error, no failed node, no guard reason, audit SUCCESS.
//
// The system prompt already said "NEVER invent a rate, a tenure, a down payment
// or an approval." It said it clearly and the model ignored it. A prompt is not
// a control. Telling a model not to calculate is not the same as making it
// impossible for the calculation to reach a customer.
//
// The principle this layer enforces:
//   The AI may EXPLAIN an authoritative finance result.
//   The AI is NEVER the authority for a finance calculation.
//
// So: if the outgoing message asserts a finance figure, there must be evidence
// that finance_calculator actually ran IN THIS TURN and actually produced the
// class of figure being asserted. No evidence -> block. And crucially, a run
// that returned an APR but no instalment does NOT authorise an instalment --
// that is the exact shape of the incident and the whole point of the layer.
//
// Deliberately NOT blocked: the car's own price, a cash discount offer, a plain
// availability line. Those are the dealership's own numbers, not the bank's.

// -- 5a. Position helpers ----------------------------------------------------
// Proximity is computed on match POSITIONS rather than with one giant lookaround
// regex, so each figure class stays readable and auditable on its own.
function finPositions(re, s) {
  const out = [];
  const r = new RegExp(re.source, re.flags.indexOf('g') === -1 ? re.flags + 'g' : re.flags);
  let m;
  while ((m = r.exec(s)) !== null) {
    out.push([m.index, m.index + m[0].length]);
    if (m[0].length === 0) r.lastIndex++;
    if (out.length > 200) break;
  }
  return out;
}
// True when any A match sits within `span` characters of any B match, either
// side. Overlaps give a negative gap and therefore also count.
function finNear(A, B, span) {
  for (let i = 0; i < A.length; i++) {
    for (let j = 0; j < B.length; j++) {
      const a = A[i], b = B[j];
      const gap = a[0] < b[0] ? b[0] - a[1] : a[0] - b[1];
      if (gap <= span) return true;
    }
  }
  return false;
}

// -- 5b. What counts as money -----------------------------------------------
// Either a currency-tagged number, or a thousands-GROUPED number. A bare
// ungrouped run of digits only counts at 5+ digits, which keeps model years
// ("Lexus LX 600 2024") and tenures ("60 months") out of the money set --
// a 2024 read as money would have made the availability line unsendable.
// Group separators include a plain space because the live incident wrote
// "AED 585 000" and "AED 11 200" with spaces, not commas.
const FIN_MONEY_RE = /(?:aed|dhs?|dirhams?|د\.إ)\s*\d[\d.,   ]*\d|\d[\d.,   ]*\d\s*(?:aed|dhs?|dirhams?)\b|\b\d{1,3}(?:[,   ]\d{3})+\b|\b\d{5,}\b/gi;
const FIN_PCT_RE = /\d{1,3}(?:\.\d+)?\s*(?:%|per\s?cent\b|percent\b)/gi;

// Keyword sets, one per figure class.
// Two of these classes have a STRONG and a WEAK half, because the obvious
// keyword list over-blocks ordinary sales lines. The probes that forced the
// split, all of which must send:
//   "The price is AED 585,000 and delivery is in two months."
//   "We have had this one for a few months. Price AED 585,000."
//   "I can hold it with a small deposit and the price stays AED 585,000."
// A bare "months" is a duration; only "monthly", "per month", "EMI", "kist"
// and friends are inherently about a payment. Likewise a bare "deposit" sitting
// in the same sentence as the car's price is not a down-payment quote.

// STRONG monthly words -- these alone make a nearby money figure an instalment.
const FIN_MONTH_KW  = /(?:\bmonthly\b|per\s?month\b|a\s+month\b|\bemi\b|\binstal\w*|\bmahina\b|\bmahine\b|\bkist\w*|\bqist\w*|p\s?\/\s?m\b|\/mo\b|\/month\b)/gi;
// WEAK: a bare "month(s)". Counts only when a payment word is also close by.
const FIN_MONTH_WEAK_KW = /\bmonths?\b/gi;
const FIN_PAY_KW    = /(?:\bpay(?:ment|ments|able|ing)?\b|\brepay\w*|\bfinanc\w*|\bloan\b|\btenure\b|\bterm\b|\binstal\w*|\bemi\b)/gi;

const FIN_APR_KW    = /(?:\bapr\b|\binterest\b|\brates?\b|\breducing\b|\bflat\s+rate\b|\bprofit\s+rate\b)/gi;

// STRONG down-payment words.
const FIN_DOWN_KW   = /(?:\bdown[\s-]?payment\b|\bdownpayment\b)/gi;
// WEAK: "deposit" / "advance" are ordinary sales words, so the money has to be
// grammatically attached ("a deposit of AED 20,000"), not merely in the sentence.
const FIN_DOWN_WEAK_KW = /(?:\badvance\b|\bdeposit\b)/gi;

const FIN_TENURE_KW = /(?:\bover\s+\d{1,3}\s*months?\b|\b\d{1,3}\s*[-–]\s*month\b|\b\d{1,3}\s+months?\b)/gi;

const finMoney  = finPositions(FIN_MONEY_RE, text);
const finPct    = finPositions(FIN_PCT_RE, text);

// Spans are short on purpose. 40 chars is about a clause; a money figure and a
// payment word that far apart are almost always the same assertion.
const claims = [];
{
  // A weak "months" is promoted to a monthly keyword only when a payment word
  // sits within 30 chars of it -- "over 60 months of payments" yes,
  // "delivery is in two months" no.
  const pay = finPositions(FIN_PAY_KW, text);
  let mk = finPositions(FIN_MONTH_KW, text);
  if (pay.length) {
    for (const w of finPositions(FIN_MONTH_WEAK_KW, text)) if (finNear([w], pay, 30)) mk.push(w);
  }
  if (finMoney.length && mk.length && finNear(finMoney, mk, 40)) claims.push('monthly_payment');
}
if (finPct.length && finNear(finPct, finPositions(FIN_APR_KW, text), 40)) claims.push('apr');
{
  const dn = finPositions(FIN_DOWN_KW, text);
  const dw = finPositions(FIN_DOWN_WEAK_KW, text);
  const strong = dn.length && (finNear(finMoney, dn, 40) || finNear(finPct, dn, 40));
  const weak   = dw.length && (finNear(finMoney, dw, 18) || finNear(finPct, dw, 18));
  if (strong || weak) claims.push('down_payment');
}
// A tenure is only a finance assertion when money is attached to it AND a
// payment word is in play. "Delivery takes about two months" carries no figure,
// and "price AED 585,000, delivery is in 2 months" is a delivery date sitting
// near a car price -- neither is a repayment claim.
{
  const tn = finPositions(FIN_TENURE_KW, text);
  const pay2 = finPositions(FIN_PAY_KW, text);
  if (finMoney.length && tn.length && pay2.length &&
      finNear(finMoney, tn, 60) && finNear(tn, pay2, 40)) claims.push('tenure');
}

// -- 5c. Evidence ------------------------------------------------------------
// Read defensively and never throw. $('finance_calculator') THROWS when that
// node did not run in this execution -- it does not return undefined -- and in
// a plain Code-node context `$` may not exist at all. Both land in the catch.
let ev = {};
try { ev = $('finance_calculator').last().json || {}; } catch (e) { ev = {}; }

// The agent may also carry the result forward on the item itself. Only a
// whitelist of fields is honoured, so a model cannot mint evidence by writing
// arbitrary keys into its own output.
const EV_CARRY = ['finance_calculation_id', 'finance_execution_id', 'calculation_id',
                  'execution_id', 'emi_available', 'quotable', 'monthly_payment_low_aed',
                  'monthly_payment_high_aed', 'indicative_apr_low_pct', 'indicative_apr_high_pct',
                  'down_payment_aed', 'tenure_months', 'calculated_at', 'status'];
const carried = {};
for (const k of EV_CARRY) if (prev && prev[k] !== undefined && prev[k] !== null) carried[k] = prev[k];
ev = Object.assign({}, carried, ev);

function evHas(k) { return ev[k] !== undefined && ev[k] !== null && ev[k] !== ''; }

// An identifier is what proves a RUN happened, as opposed to a number the model
// simply typed. calculated_at counts: finance_calculator stamps it per run.
const EV_ID_KEYS = ['finance_calculation_id', 'finance_execution_id', 'calculation_id',
                    'execution_id', 'calculated_at', 'calculatedAt'];
let evHasId = false;
for (const k of EV_ID_KEYS) if (evHas(k)) { evHasId = true; break; }

// A failed or non-quotable run authorises nothing at all.
const evStatus = String(ev.status || '').toLowerCase();
const evUsable = evHasId && evStatus !== 'error' && evStatus !== 'input_error';
const evQuotable = ev.quotable !== false;
// emi_available === false is an explicit statement that NO instalment exists.
// It vetoes a monthly claim even if some stale monthly number is lying around.
const evEmiOk = ev.emi_available !== false;

// The discrimination that matters: each class needs ITS OWN figure present.
function authorised(cls) {
  if (!evUsable) return false;
  if (cls === 'monthly_payment') return evQuotable && evEmiOk && evHas('monthly_payment_low_aed');
  if (cls === 'apr')             return evQuotable && evHas('indicative_apr_low_pct');
  if (cls === 'down_payment')    return evHas('down_payment_aed');
  // A money-bearing tenure claim is an instalment claim in other words, so it
  // is satisfied by an instalment or by an explicit tenure from the calculator.
  if (cls === 'tenure')          return evQuotable && evEmiOk &&
                                        (evHas('monthly_payment_low_aed') || evHas('tenure_months'));
  return false;
}

const financeClaimDetected = claims.length > 0;
const unauthorised = [];
for (const c of claims) if (!authorised(c)) unauthorised.push(c);
const financeEvidenceOk = financeClaimDetected ? unauthorised.length === 0 : true;

// Reasons from layers 1-4 decide which fallback the customer sees, so capture
// the count BEFORE this layer adds its own.
const preFinanceReasonCount = reasons.length;
for (const c of unauthorised) reasons.push('finance figure without calculator evidence: ' + c);

// -- Fallbacks ---------------------------------------------------------------
const FALLBACK = "Sorry, that didn't come out right on my side. Let me get you a proper answer - one moment.";
// A finance block is not a malfunction the customer should feel. It is a
// promise of a real number instead of a guessed one, and it keeps the thread
// alive rather than ending on an apology.
const FINANCE_FALLBACK = "Let me get you the exact monthly figure from our finance desk rather than guess - one moment. Meanwhile, is there anything else about the car I can answer?";

const blocked = reasons.length > 0;
const safe = blocked
  ? (preFinanceReasonCount > 0 ? FALLBACK : FINANCE_FALLBACK)
  : text;

return [{ json: {
  ...prev,
  output: safe,
  guard_blocked: blocked,
  guard_reasons: reasons,
  raw_output: text,
  finance_claim_detected: financeClaimDetected,
  finance_evidence_ok: financeEvidenceOk,
  finance_claim_classes: claims
} }];

// Stop a second INITIAL_OUTREACH to a lead we already messaged in the last 24h.
// On 16 Aug the router was posted twice and the customer got two near-identical
// welcome messages 4 minutes apart. Inbound replies are never blocked - only
// proactive outreach.
const ctx = $('Resolve Lead Identity').first().json;
const isOutreach = ctx.direction === 'outbound' ||
                   String(ctx.message || '').startsWith('INITIAL_OUTREACH:');

if (!isOutreach) return [{ json: ctx }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
if (rows.length > 0) {
  // Already contacted recently -> return nothing, which halts this branch.
  return [];
}
return [{ json: ctx }];

// This workflow runs with binaryMode "separate", so n8n keeps binary payloads
// on disk and binary.data.data is a REFERENCE, not base64. Reading it directly
// sent garbage to the vision model ("Bad request - Provider returned error").
// getBinaryDataBuffer() is the only way that works in both binary modes.
const ctx = $('Resolve Lead Identity').first().json;
const bin = ($input.first().binary || {}).data;
if (!bin) {
  throw new Error('KYC image download produced no binary property - check the WAHA file URL and API key.');
}
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buf.toString('base64');
if (!b64 || b64.length < 100) {
  throw new Error('KYC image decoded to ' + b64.length + ' base64 chars - too small to be a document.');
}
return [{ json: {
  document_base64: b64,
  mime_type: bin.mimeType || 'image/jpeg',
  size_bytes: buf.length,
  chat_id: ctx.sender,
  lead_email: ctx.lead_email,
  lead_name: ctx.lead_name,
  // 2 Sep 2026: the KYC auditor writes kyc_documents rows. Without this it
  // would write them under whichever tenant holds is_unattributed_default,
  // i.e. a second dealership's Emirates ID would land in the first
  // dealership's compliance screen.
  tenant_id: ctx.tenant_id || null
} }];

// Every node whose success this run is about to claim.
const CLAIMED = [
  { node: 'Send Reply via WAHA HTTP API', what: 'WhatsApp reply to the customer', critical: true },
  { node: 'Log Conversation',             what: 'communication_logs row for the reply', critical: false },
  { node: 'Claim Message Id',             what: 'idempotency claim in processed_messages', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

// 30 Aug 2026: a voice note adds a FOURTH, non-critical claim -- but only on
// runs where the voice branch actually ran. Adding it to CLAIMED unconditionally
// would make check() report 'node did not run on this branch' for every text
// message and turn every text run PARTIAL.
let voiceClaim = null;
try {
  const mt = $('Merge Voice Transcript');
  if (mt && (mt.isExecuted === undefined || mt.isExecuted)) {
    const v = mt.first().json || {};
    voiceClaim = {
      what: 'voice note transcription',
      critical: false,
      ok: v.voice_transcribed === true,
      why: v.voice_transcribed === true ? '' : String(v.voice_drop_reason || 'transcription failed').slice(0, 300),
    };
  }
} catch (e) { voiceClaim = null; }

// 02 Sep 2026: Guard Reply substitutes a holding sentence when it blocks, so
// the customer never sees the leak -- but until now NOTHING recorded that a
// block had happened. The run wrote SUCCESS, the audit row said 'all 3 claimed
// steps verified', and no human ever learned that a real answer was suppressed.
// A suppressed reply is a customer left waiting on something the bot could not
// safely say, which is precisely the case a human must pick up. Report it
// through the Delivery Report -> audit_log path this workflow already uses,
// rather than adding a second escalation channel.
// Non-critical on purpose: the customer DID receive the holding sentence, so
// the run is PARTIAL (needs a human), not FAILED (delivery broke).
let guardClaim = null;
try {
  const g = $('Guard Reply').first().json || {};
  if (g.guard_blocked === true) {
    guardClaim = {
      what: 'AI reply suppressed by Guard Reply - NEEDS HUMAN FOLLOW-UP',
      critical: false,
      ok: false,
      why: (Array.isArray(g.guard_reasons) ? g.guard_reasons.join('; ') : String(g.guard_reasons || 'blocked')).slice(0, 300),
    };
  }
} catch (e) { guardClaim = null; }

const results  = CLAIMED.map(check);
if (voiceClaim) results.push(voiceClaim);
if (guardClaim) results.push(guardClaim);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
}, pairedItem: { item: 0 } }];

// Make.com used to do this: take a raw inbound enquiry and hand the Master
// Router a lead-shaped object. Make.com is empty now -- every workflow was
// moved into n8n -- so WhatsApp is the live inbound channel and this is where
// the shaping happens.
//
// `Validate & Enrich Input` on the Router accepts `.body`, `.lead`, or a bare
// object, and needs an email OR a phone. We have the phone.
const ctx = $('Resolve Lead Identity').first().json;

const digits = String(ctx.sender_phone || '').replace(/[^0-9]/g, '');
if (!digits) return [];   // nothing the Router could key a lead on

return [{ json: {
  name: ctx.lead_name || ctx.push_name || 'WhatsApp enquiry',
  phone: '+' + digits,
  email: ctx.lead_email || null,
  message: ctx.message || null,
  vehicle_interest: ctx.message || null,
  source: 'whatsapp',
  // 2 Sep 2026: the Router CREATES the lead row. The tenant has to travel with
  // the lead or the Router files a second dealership's customer inside the
  // first dealership's tenant -- the exact failure this whole pass is about.
  tenant_id: ctx.tenant_id || null,
  // Tells the Router the customer is ALREADY in a live thread, so it scores,
  // alerts and syncs but does NOT fire a canned welcome on top of the reply
  // the BDC agent has just sent them.
  origin: 'whatsapp-bdc',
} }];

// Human Spoke Recently?  — added by the human-handover handoff.
//
// Collapses `Human Reply Check` (0 or 1 row, or 1 error item) into EXACTLY ONE
// item carrying the Resolve Lead Identity context plus a mode. Every node after
// this one runs once per item, so returning anything other than one item would
// multiply the whole reply chain.
//
// THE TWO WINDOWS. Both live here and nowhere else.
//   HARD_SILENCE_MIN  30  — a rep spoke within the last 30 minutes: the bot says
//                           NOTHING. A WhatsApp haggle runs at minutes per turn,
//                           and the failure this fixes ("I can do 78,000 final"
//                           / "ok" / bot quotes its own number) happens inside
//                           one of those turns. 30 minutes also covers the rep
//                           putting the phone down to walk the lot. It does not
//                           strand the customer: by definition a person is on
//                           this thread right now.
//   SUPERVISED_HOURS  12  — from 30 minutes to 12 hours the bot DOES answer,
//                           instantly, but its prompt is told a colleague is
//                           already in this conversation and it must not touch
//                           any number that colleague named. A customer who
//                           writes the next morning is past 12h and gets normal
//                           service; a customer who writes at midnight after a
//                           7pm rep message still gets an instant answer, just a
//                           careful one. Full silence for 12h would be the cure
//                           killing the patient.
//
// FAIL DIRECTION. If the lookup could not be done (Supabase down, malformed
// or=() filter, PostgREST 400) we do NOT know whether a rep is mid-negotiation.
// That degrades to 'supervised', not to 'normal': the customer still gets an
// instant reply, but one that cannot contradict a colleague. Zero rows is a real
// answer, not an error, and gives 'normal'.
const HARD_SILENCE_MIN = 30;
const SUPERVISED_HOURS = 12;

let ctx = {};
try { ctx = $('Resolve Lead Identity').first().json || {}; } catch (e) { ctx = {}; }

const rows = $input.all().map(i => (i && i.json) || {});
const errored = rows.some(r => r.error !== undefined && r.error !== null);
const hit = rows.find(r => r && r.created_at);

let mode = 'normal';
let human_minutes = null;
let last_human_by = '';
let last_human_message = '';

if (hit) {
  const t = new Date(hit.created_at).getTime();
  if (isNaN(t)) {
    mode = 'supervised';
  } else {
    human_minutes = Math.max(0, Math.round((Date.now() - t) / 60000));
    last_human_by = String(hit.sent_by || 'a colleague');
    last_human_message = String(hit.message || '').replace(/\s+/g, ' ').trim().slice(0, 400);
    mode = human_minutes < HARD_SILENCE_MIN ? 'silent'
         : human_minutes < SUPERVISED_HOURS * 60 ? 'supervised'
         : 'normal';
  }
} else if (errored) {
  mode = 'supervised';
}

// The block the agent prompt prepends. Empty unless we are supervising.
let handover_note = '';
if (mode === 'supervised') {
  handover_note =
    'HANDOVER NOTE — READ THIS BEFORE ANSWERING. A human colleague from the dealership is already '
    + 'handling this conversation on this same WhatsApp number'
    + (human_minutes === null
        ? '.'
        : '; their last message to this customer was ' + human_minutes + ' minutes ago'
          + (last_human_message ? ' and it said: "' + last_human_message + '"' : '.'))
    + '\n'
    + 'Do NOT contradict your colleague. Do NOT restate, improve, reduce, re-confirm or withdraw any '
    + 'price, discount, figure, deadline or commitment they have made, and do NOT make a commercial '
    + 'offer of your own in this thread. Answer only the factual part of what the customer just asked '
    + '— stock, specification, availability, timing, policy. If they are asking about price, payment, '
    + 'discount, part-exchange value or anything already being negotiated, say your colleague is '
    + 'looking after that and will come straight back to them, and stop there. Keep it to one or two '
    + 'short lines and do not open a new topic.';
}

return [{ json: {
  ...ctx,
  human_mode: mode,
  human_minutes,
  last_human_by,
  last_human_message,
  handover: mode === 'supervised',
  handover_note,
  human_check_errored: errored
}, pairedItem: { item: 0 } }];

// Prepare Voice Upload
// Validates the WAHA download, applies the duration cap, and normalises the
// binary metadata so Groq accepts the multipart upload.
//
// Deliberately does NOT call this.helpers.getBinaryDataBuffer(): the workflow
// runs with binaryMode "separate", so the audio bytes live outside the item.
// Pulling them into the heap of a 958 MB box buys nothing -- only the binary
// METADATA is needed, and n8n streams the file itself at upload time.
const MAX_SECONDS = 180;

// Duration comes from `Extract Message & Sender`, which read it off
// payload._data.Message.audioMessage.seconds. No webhook reach-back is needed:
// the outreach entry path (`Called by Master Router`) never sets is_voice, so
// this node is unreachable from it.
let ex = {};
try { ex = $('Extract Message & Sender').first().json || {}; } catch (e) { ex = {}; }
const seconds = Number(ex.audio_seconds || 0);

const out = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const binary = item.binary || {};

  let ok = true;
  let reason = '';

  if (json.error !== undefined && json.error !== null) {
    // `Download Voice Note` runs with onError: continueRegularOutput, so a 404
    // after WHATSAPP_FILES_LIFETIME (180s) expiry lands here as data, not a throw.
    ok = false;
    reason = 'waha download failed: ' + String((json.error && (json.error.message || json.error.description)) || json.error).slice(0, 200);
  } else if (!binary.data) {
    ok = false;
    reason = 'waha returned no audio body (file expired, 404, or media was never stored)';
  } else if (seconds > MAX_SECONDS) {
    ok = false;
    reason = 'voice note is ' + seconds + 's, over the ' + MAX_SECONDS + 's cap';
  } else if (!String(binary.data.mimeType || ex.audio_mime || '').toLowerCase().startsWith('audio/')) {
    ok = false;
    reason = 'unsupported mimetype: ' + String(binary.data.mimeType || ex.audio_mime || 'unknown');
  }

  if (ok) {
    // Groq rejects an upload whose filename carries no recognised audio
    // extension. WAHA sets media.filename to null for audio, and n8n then falls
    // back to the URL basename or the literal "data". Force it.
    item.binary.data.fileName = 'voice.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }

  out.push({
    json: {
      voice_ok: ok,
      voice_drop_reason: reason,
      voice_seconds: seconds,
      voice_mime: String(ex.audio_mime || 'audio/ogg; codecs=opus'),
    },
    binary: ok ? item.binary : undefined,
    pairedItem: { item: 0 },
  });
}
return out;

// Merge Voice Transcript
// Single join point for both legs: Groq success/failure, and the give-up leg
// from `Voice Is Usable?` false. It NEVER throws and it always emits exactly
// one item, so the customer is never met with silence because of this branch.
const j = ($input.first() || {}).json || {};

// The Groq HTTP node REPLACES the item, so the pre-flight verdict has to be
// read back from `Prepare Voice Upload` explicitly.
let prep = {};
try { prep = $('Prepare Voice Upload').first().json || {}; } catch (e) { prep = {}; }

let transcript = '';
let language = null;
let reason = String(prep.voice_drop_reason || '');

if (!reason) {
  // We came through Groq.
  if (j.error !== undefined && j.error !== null) {
    reason = 'groq: ' + String((j.error && (j.error.message || j.error.description)) || j.error).slice(0, 200);
  } else {
    transcript = String(j.text ?? '').trim();
    language = j.language ? String(j.language) : null;
    if (!transcript) reason = 'groq returned an empty transcript';
  }
}

const ok = !reason && !!transcript;

// The fallback is an INSTRUCTION to the agent, not a canned string sent to the
// customer -- that is the only way the apology comes back in the customer's own
// language. Same convention as the INITIAL_OUTREACH: prefix that
// `Extract Message & Sender` already injects for router-initiated outreach.
//
// The drop reason is deliberately NOT interpolated into this text. It flows
// downstream into `Reply Eligibility`, whose 73-keyword allowlist is a substring
// match -- an arbitrary Groq error string could contain "model" or "service" and
// silently widen the allowlist for an unknown number.
const NOTE = 'SYSTEM_NOTE: This person sent a WhatsApp voice message and we were not able to turn it into text. Do not guess what they said. Reply briefly, in whatever language they have been writing in, say sorry you missed it, and ask them to write it out or send a shorter recording.';

return [{ json: {
  message: ok ? transcript : NOTE,
  is_voice: true,
  voice_transcribed: ok,
  voice_transcript: ok ? transcript : '',
  voice_language: language,
  voice_seconds: Number(prep.voice_seconds || 0),
  voice_drop_reason: ok ? '' : reason,
}, pairedItem: { item: 0 } }];

// WAHA Auth Gate
// -----------------------------------------------------------------------------
// Sits on the ONLY public path into this workflow: POST /webhook/whatsapp-inbound.
// Before this node existed, ANY caller on the internet who knew that URL could
// drive the whole chain below: make the dealership's own WhatsApp number send a
// message to any phone number it chose (`Send Reply via WAHA HTTP API` sends to
// `body.payload.from`, which is caller-supplied), burn OpenRouter and Groq
// credits, and write rows into communication_logs, whatsapp_contacts,
// processed_messages and leads.
//
// The other entry point, `Called by Master Router` (executeWorkflowTrigger ->
// Extract Message & Sender), does NOT pass through here and is unchanged.
//
// WHAT THIS DOES NOT DO: `WAHA Webhook (POST)` responds onReceived, so the HTTP
// 200 is already on the wire before this node runs. An unauthorised caller still
// gets a 200. What the gate buys is that NOTHING HAPPENS for that caller: no
// WhatsApp send, no model call, no database write. Do not describe it as
// returning 401. It is also why a misconfigured secret can never make WAHA think
// the endpoint is broken and back off -- WAHA keeps seeing 200 either way.
//
// THREE STATES, all driven by container env vars (the established $env pattern
// here; N8N_BLOCK_ENV_ACCESS_IN_NODE=false):
//
//   WAHA_WEBHOOK_SECRET unset/empty  -> DORMANT. Every item passes, exactly as
//                                        before this node existed. This is the
//                                        env-level rollback. THIS IS THE STATE
//                                        THE BOX IS IN UNTIL ALI SETS THE VAR,
//                                        AND IT IS NOT A SAFE RESTING STATE.
//   secret set, WAHA_WEBHOOK_ENFORCE != 'true'
//                                    -> MONITOR. Every item passes, tagged, so
//                                        you can confirm in the execution list
//                                        that WAHA is really sending the header
//                                        BEFORE you enforce.
//   secret set, WAHA_WEBHOOK_ENFORCE == 'true'
//                                    -> ENFORCE. Items without a matching header
//                                        are dropped (return [] -> nothing
//                                        downstream runs). No throw, so an
//                                        attacker generates no error-workflow
//                                        alert storm.
//
// 3 Sep 2026 -- TWO CHANGES, both about being able to SEE what state this is in.
//
// 1. `_gate` IS NOW EMITTED IN EVERY STATE, and carries `mode`.
//    The previous version returned the items untouched when dormant, so the way
//    to tell DORMANT from MONITOR was the ABSENCE of the `_gate` key. That is a
//    terrible signal: absence is also what you get from a node that did not run,
//    a node that was disabled, and an older published version. An audit on 3 Sep
//    had to run the workflow with a payload that dies before any write purely to
//    observe that absence. Read `_gate.mode` instead. `ok`, `header_present` and
//    `enforcing` are kept with their old meanings so nothing that reads them
//    breaks.
//
// 2. ENFORCE WITHOUT A SECRET NOW FAILS CLOSED.
//    Previously the dormant check came first, so `WAHA_WEBHOOK_ENFORCE=true`
//    with an empty/typo'd/commented-out `WAHA_WEBHOOK_SECRET` passed EVERYTHING
//    -- an operator who had explicitly asked for enforcement silently got an
//    open endpoint. That is the worst possible direction for a misconfiguration
//    to fail. It now drops everything instead. The failure is then loud in the
//    only way that matters commercially (the bot stops replying, Ali notices in
//    minutes) rather than silent and open.
//
// The `_gate` key it adds is inert: `Prefilter` is a Set node in assignments
// mode with includeOtherFields off, so it emits only its four assignments and
// _gate never reaches anything else. `Extract Message & Sender` reaches back
// with $('WAHA Webhook (POST)') by name, which is unaffected by this insertion.
//
// FASTEST ROLLBACK (no restart, no env change, ~10 seconds): open this workflow
// in the n8n editor, right-click this node, "Deactivate"/disable it, save. A
// disabled node passes its input straight through to its output, so the channel
// is instantly back to its pre-patch behaviour.
const EXPECTED = String($env.WAHA_WEBHOOK_SECRET || '');
const ENFORCE  = String($env.WAHA_WEBHOOK_ENFORCE || '').trim().toLowerCase() === 'true';
const HEADER   = 'x-nexus-webhook-secret';

const items = $input.all();

// MISCONFIGURED ENFORCE -> fail closed. See note 2 above. Nothing downstream
// runs; the saved execution shows this node emitting zero items, which is the
// evidence that the secret is missing rather than the header being wrong.
if (ENFORCE && !EXPECTED) {
  return [];
}

const MODE = !EXPECTED ? 'DORMANT' : (ENFORCE ? 'ENFORCE' : 'MONITOR');

// Length-independent-ish constant-time compare. Not a defence against a remote
// timing attack over the public internet (network jitter dwarfs it) -- it is
// here because comparing secrets with === is a habit worth not having.
function sameSecret(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const headers = (item.json && item.json.headers) || {};

  // Node lower-cases inbound header names, but do not rely on it.
  let got = '';
  for (const k of Object.keys(headers)) {
    if (String(k).toLowerCase() === HEADER) { got = String(headers[k] == null ? '' : headers[k]); break; }
  }

  const present = got !== '';
  const ok = present && !!EXPECTED && sameSecret(got, EXPECTED);

  // ENFORCE and not ok -> silently dropped. No throw, no log, no cost.
  if (MODE === 'ENFORCE' && !ok) continue;

  out.push({
    json: Object.assign({}, item.json, {
      _gate: { mode: MODE, ok: ok, header_present: present, enforcing: MODE === 'ENFORCE' }
    }),
    binary: item.binary,
    pairedItem: { item: i }
  });
}

return out;

// NEXUS - Resolve Tenant  (inbound WhatsApp)
// ---------------------------------------------------------------------------
// WHY THIS NODE EXISTS
// n8n talks to Supabase as service_role. service_role is BYPASSRLS and carries
// no auth.uid(), so every row n8n writes without an explicit tenant_id falls
// back to the column DEFAULT, public.nexus_default_tenant_id(), which for an
// unauthenticated writer resolves to whichever tenant holds
// tenants.is_unattributed_default. That is dealership ONE. A second
// dealership's customers would be created inside dealership one's tenant:
// visible to their staff, invisible to their own. No RLS policy can fix that -
// the row is genuinely stamped with the wrong owner. This node is where the
// guessing stops.
//
// THE SIGNAL, AND WHY IT IS STILL THE RIGHT ONE
// The WAHA session the message arrived on. One WAHA session == one WhatsApp
// Business number == one dealership. WAHA puts it on the webhook body as
// `session`. That IS the correct signal: it describes which of the dealership's
// own numbers the message landed on, which is exactly the question being asked.
// Deleting it and inventing something else would throw away the only real
// evidence in the request.
//
// 3 Sep 2026 -- WHAT WAS ACTUALLY WRONG WITH IT
// The signal was never the defect. The defect was that it was UNAUTHENTICATED
// and UNVALIDATED, and that a value which failed to validate was rescued by a
// default instead of refused:
//
//   unauthenticated -> anyone who could reach POST /webhook/whatsapp-inbound
//     could type any session they liked. That is closed by `WAHA Auth Gate`
//     upstream (a shared secret proving the sender really is WAHA), not here.
//     This node cannot fix it and should not pretend to.
//   unvalidated -> the old code accepted a session that was NOT in the map and
//     then fell through to `sole_configured_tenant`, i.e. dealership one. So an
//     unknown session did not fail; it landed in the live dealership's books.
//     With two dealerships configured the same JSON field would have chosen
//     between them. THAT is what is fixed here.
//
// THE RULE NOW: ALLOWLIST, AND REFUSE RATHER THAN DEFAULT.
// A session resolves a tenant if and only if it is a key of the map and maps to
// a UUID. Anything else -- unknown session, empty session, absent session,
// non-UUID value -- returns NO ITEMS. Nothing downstream runs: no message id is
// claimed, no contact upserted, no reply sent, no lead created, no audit row.
// There is deliberately no fallback and no default. `sole_configured_tenant` is
// gone from this path: "we only have one dealership so it must be theirs" is
// exactly the reasoning that turns an unidentified message into their customer.
//
// Note the two locks are independent and both are needed. The gate answers "is
// this really WAHA?". This node answers "which of our numbers did it arrive
// on?". A dormant gate does not make this node unsafe, and this node does not
// make a dormant gate safe.
//
// THE MAP
// $env.NEXUS_TENANT_MAP, a JSON object { "<waha session>": "<tenant uuid>" }.
// If it is unset or unparseable we fall back to BUILTIN below, whose single key
// `default` is the live WAHA session name on this box (confirmed: `Send Reply
// via WAHA HTTP API` posts session 'default', and the infra probe reads
// /api/sessions/default). Onboarding dealership two means adding its session
// here, in one place, and nothing else changes.
//
// LIVE-PATH RISK, STATED PLAINLY. The one way this change can hurt the live
// dealership is if WAHA on this box does not put `session` on the webhook body
// at all -- then every real customer message is refused. That has NOT been
// observed on this box (no real inbound message has run through a saved
// execution since 2 Sep, so there is no captured body to read), which is why
// the very first step of the rollout is Ali sending himself one WhatsApp and
// confirming a reply. If it breaks, the 10-second rollback is to disable THIS
// node in the editor: a disabled node passes its input straight through, and
// `Extract Message & Sender` then yields tenant_id null, which is precisely the
// pre-patch behaviour.
const BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let map = {};
try { map = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { map = {}; }
if (!map || typeof map !== 'object' || Array.isArray(map) || !Object.keys(map).length) map = BUILTIN;

// The webhook body is no longer on the item here: Prefilter is a Set node with
// includeOtherFields off, so it emits only its four assignments. Reach back to
// the trigger by name - the established pattern in this workflow.
let session = '';
try { session = String((($('WAHA Webhook (POST)').first().json || {}).body || {}).session || '').trim(); }
catch (e) { session = ''; }

// hasOwnProperty, not `in` and not map[session] directly: a caller-supplied
// session of 'constructor' or 'toString' must not reach an inherited member.
const claimed = (session && Object.prototype.hasOwnProperty.call(map, session))
  ? String(map[session] == null ? '' : map[session])
  : '';

if (!UUID.test(claimed)) {
  // FAIL CLOSED. No tenant, no run. The saved execution still shows the webhook
  // body, so the rejected session is visible in the execution list without this
  // node writing anything an unauthenticated caller could have caused.
  return [];
}

return $input.all().map((item, i) => ({
  json: Object.assign({}, item.json, {
    tenant_id: claimed,
    tenant_source: 'waha_session',
    waha_session: session
  }),
  binary: item.binary,
  pairedItem: { item: i }
}));

// Reached either straight from `Called by Master Router` (outreach) or from
// `Is New Message?`. In the second case the item we are handed is the dedupe
// guard's HTTP response, not the webhook body -- an HTTP node's output REPLACES
// the item -- so reach back to the webhook node for the real payload.
let item = $input.first().json;
if (!item.lead && !item.body && !item.payload) {
  try { item = $('WAHA Webhook (POST)').first().json; } catch (e) { /* outreach path */ }
}

// ---- TENANT (2 Sep 2026) --------------------------------------------------
// Both entry points converge on this node, so this is where the dealership is
// settled once and becomes a value every downstream write carries explicitly.
// Writing without it means service_role (BYPASSRLS, no auth.uid()) lets the
// column default file the row under whichever tenant holds
// is_unattributed_default -- i.e. under dealership one, whoever actually sent
// the message.
//   webhook path  -> `Resolve Tenant` already derived it from the WAHA session,
//                    and REFUSED THE WHOLE RUN if that session was not on the
//                    allowlist, so by the time we are reached on this path the
//                    dealership is already settled. There is no second guess to
//                    make and none is made.
//   outreach path -> the Master Router hands it to us on the lead object.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);
//
// 3 Sep 2026: THE TWO ENTRY POINTS NOW GET DIFFERENT TREATMENT, ON PURPOSE.
// The old code ran one chain for both and ended it with "...and if none of that
// worked and exactly one dealership is configured, use that one". On the public
// webhook path that last clause was a hole: `Resolve Tenant` could refuse to
// identify the dealership and this node would quietly supply dealership one
// anyway. Whatever `Resolve Tenant` refuses must stay refused, so the webhook
// branch below has NO fallback of any kind. The outreach branch keeps the old
// chain unchanged -- it is reached only from `Called by Master Router`, i.e.
// from inside n8n's own trust boundary, and the Router has already resolved the
// dealership from a verified JWT or from the WAHA session.
let TENANT = '';
if (item.lead) {
  // OUTREACH (internal caller). Unchanged.
  TENANT = String(item.lead.tenant_id || '');
  if (!NEXUS_UUID.test(TENANT) && nexusKeys.length === 1) TENANT = String(nexusMap[nexusKeys[0]] || '');
} else {
  // WEBHOOK. The ONLY acceptable source is `Resolve Tenant`, which refuses
  // unless the WAHA session is on the allowlist. If that node has been disabled
  // as an emergency rollback this evaluates to null, the writes below omit
  // tenant_id, and the column default applies -- i.e. exactly the pre-patch
  // behaviour, which is what makes disabling it a safe rollback.
  try { TENANT = String(($('Resolve Tenant').first().json || {}).tenant_id || ''); } catch (e) { TENANT = ''; }
}
if (!NEXUS_UUID.test(TENANT)) TENANT = null;

if (item.lead) {
  const lead = item.lead;
  const interest = lead.vehicle_interest || lead.vehicleInterest || lead.message || 'a vehicle';
  let chatId = String(lead.phone || lead.whatsapp || '').trim();
  if (!chatId) return [];
  if (!chatId.includes('@')) chatId = chatId.replace(/[^0-9]/g, '') + '@c.us';
  return [{ json: {
    message: 'INITIAL_OUTREACH: Lead name: ' + (lead.name || 'there') + ', interested in: ' + interest + '. Send them a warm, personalised WhatsApp welcome message introducing the NEXUS OS dealership and asking how you can help.',
    sender: chatId,
    lead_email: lead.email || null,
    tenant_id: TENANT,
    direction: 'outbound',
    is_voice: false,
    // Outreach is not a WAHA delivery. Give it a unique id so the idempotency
    // guard downstream always lets it through.
    message_id: 'outreach:' + Date.now() + '-' + Math.random().toString(36).slice(2, 10)
  } }];
}

const body = item.body || item;
const payload = body.payload || {};

const event = String(body.event || '');
if (event && event !== 'message') return [];

// Never reply to our own messages -> this is what caused the infinite loop
if (payload.fromMe === true) return [];

// Drop groups, status broadcasts and newsletters.
// NOTE: '@lid' is NOT filtered - WhatsApp now uses LID addressing for real
// 1:1 customer chats, so blocking it silently drops genuine messages.
const from = String(payload.from || '');
if (!from || from.endsWith('@g.us') || from.startsWith('status@') || from.endsWith('@newsletter')) return [];

// A customer sending their Emirates ID sends an IMAGE with no caption. The old
// code did `if (!text) return []` and silently dropped it - the KYC workflow was
// never reachable from WhatsApp at all. Detect media and carry it forward.
const text = typeof payload.body === 'string' ? payload.body.trim() : '';
const media = payload.media || {};
const isImage = payload.hasMedia === true && String(media.mimetype || '').startsWith('image/');

// WAHA hands back its own file URL as localhost:3000 - that is localhost *inside
// the WAHA container*. n8n must fetch it over the docker network instead.
const documentUrl = isImage
  ? String(media.url || '').replace('http://localhost:3000', 'http://waha:3000')
  : null;

// 30 Aug 2026: VOICE NOTES (PTT). Before this, a voice note had no text and a
// non-image mimetype, so `if (!text && !isImage) return []` below dropped the
// execution HERE, at node 6 of ~16. Nothing downstream ever ran, which is why
// customers who spoke instead of typing got total silence.
//
// Branch on the EXISTENCE of _data.Message.audioMessage, not on Info.MediaType:
// MediaType is 'ptt' for a held-mic recording but 'audio' for a forwarded audio
// file, and some GOWS builds omit it entirely. audioMessage is present for both.
const audioMsg = (payload._data && payload._data.Message && payload._data.Message.audioMessage) || null;
const isVoice = !!audioMsg;
const audioUrl = isVoice
  ? String(media.url || '').replace('http://localhost:3000', 'http://waha:3000')
  : null;
const audioSeconds = isVoice ? Number(audioMsg.seconds || 0) : 0;
const audioMime = isVoice ? String(media.mimetype || audioMsg.mimetype || 'audio/ogg; codecs=opus') : null;

if (!text && !isImage && !isVoice) return [];

// WhatsApp now addresses many 1:1 chats by LID (e.g. 158510264357112@lid), which
// carries NO phone number -- matching a lead on its digits is impossible. The real
// number is in _data.Info.SenderAlt. Keep `sender` as the chat id (replies must go
// back to it) and expose the true number separately for lead matching.
const info = (payload._data && payload._data.Info) || {};
const alt = String(info.SenderAlt || '');
const senderPhone = (alt.includes('@') ? alt.split('@')[0] : alt) ||
                    (from.endsWith('@lid') ? '' : from.split('@')[0]);

// WAHA has delivered the same message three times in one second, repeatedly.
// `payload.id` is the WhatsApp message id and is stable across those duplicates,
// so it is what the idempotency guard downstream claims. Fall back to
// sender+timestamp when WAHA omits it; empty means the guard cannot key on
// anything and will let the message through.
const messageId = String(payload.id || (payload.timestamp ? from + ':' + payload.timestamp : ''));

// The image placeholder must NOT be reused for audio: it contains the word
// 'document', which is in Reply Eligibility's keyword allowlist, and
// `New Lead Worth Scoring?` string-compares against it. Either way this value is
// replaced by the transcript before Resolve Lead Identity emits it.
const placeholder = isImage ? '[Customer sent a document image]' : '[Customer sent a voice note]';

return [{ json: {
  message_id: messageId,
  message: text || placeholder,
  is_document: isImage,
  document_url: documentUrl,
  is_voice: isVoice,
  audio_url: audioUrl,
  audio_seconds: audioSeconds,
  audio_mime: audioMime,
  sender: from,
  sender_phone: senderPhone,
  push_name: info.PushName || null,
  lead_email: null,
  tenant_id: TENANT,
  direction: 'inbound'
} }];

// Resolve the WhatsApp chat id back to a real lead so every log row is keyed
// on the lead's EMAIL, not on a raw chat id. Without this the silence detector
// (Phase 6) can never join communication_logs back to the leads table.
//
// Match on sender_phone (the true number pulled from Info.SenderAlt), NOT on the
// chat id -- a LID chat id has no phone digits in it at all.
const ex = $('Extract Message & Sender').first().json;

// 30 Aug 2026: VOICE NOTES. A voice note's words only exist after transcription,
// which runs between `Extract Message & Sender` and this node. Prefer that
// transcript here and nowhere else: EVERY downstream consumer of the customer's
// words reads `message` off THIS node --
//   Reply Eligibility (keyword allowlist), Model Ladder (`message: ctx.message`,
//   which overrides whatever the previous node passed), the AI agent's prompt
//   expression, Skip Duplicate Outreach, New Lead Worth Scoring?,
//   Shape Lead For Router, Log Incoming Message.
// Substituting once, here, is what makes a voice note behave exactly like text.
let voice = null;
try {
  const mt = $('Merge Voice Transcript');
  if (mt && (mt.isExecuted === undefined || mt.isExecuted)) voice = mt.first().json || null;
} catch (e) { voice = null; }
const digits = String(ex.sender_phone || ex.sender || '').replace(/[^0-9]/g, '');
const last9 = digits.slice(-9);

// A lead row is what makes `matched_lead` true, and `matched_lead` is what makes the bot
// answer someone unconditionally. So a wrong number that got written into `leads` by
// mistake would be answered forever. Marking it DISQUALIFIED in the dashboard is the
// reversible way to take it back out of the allowlist -- nothing is deleted.
//
// 2 Sep 2026 TENANCY: `Fetch All Leads` is now filtered to this message's tenant
// server-side. This second filter is belt and braces, and it is the one that
// still holds if someone widens that node again: a phone tail is only nine
// digits, and matching it against ANOTHER dealership's lead would answer their
// customer by name out of this dealership's WhatsApp number.
const leads = $input.all().map(i => i.json)
  .filter(l => l && l.phone && String(l.status || '').toUpperCase() !== 'DISQUALIFIED')
  .filter(l => !ex.tenant_id || !l.tenant_id || String(l.tenant_id) === String(ex.tenant_id));
let match = null;
if (last9.length === 9) {
  match = leads.find(l => String(l.phone).replace(/[^0-9]/g, '').slice(-9) === last9) || null;
}

return [{ json: {
  message: (voice && voice.message) ? voice.message : ex.message,
  is_document: ex.is_document || false,
  is_voice: !!voice,
  voice_transcribed: voice ? voice.voice_transcribed === true : false,
  voice_transcript: voice ? String(voice.voice_transcript || '') : '',
  voice_language: voice ? (voice.voice_language || null) : null,
  voice_seconds: voice ? Number(voice.voice_seconds || 0) : 0,
  voice_drop_reason: voice ? String(voice.voice_drop_reason || '') : '',
  document_url: ex.document_url || null,
  sender: ex.sender,
  sender_phone: ex.sender_phone || null,
  push_name: ex.push_name || null,
  direction: ex.direction,
  tenant_id: ex.tenant_id || null,
  lead_email: ex.lead_email || (match ? match.email : null),
  lead_name: match ? match.name : (ex.push_name || null),
  matched_lead: !!match
} }];

// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The previous ladder had a PAID gemini tier plus
// two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free is
// 404 free-tier-discontinued), which is why all 4 tiers failed on live traffic.
//
// 29 Aug 2026: REMOVED tier 1, 'nvidia/nemotron-3-ultra-550b-a55b:free'. It failed
// on BOTH agents inside the same real run -- exec 6251 here (46.5s wasted) and
// exec 6253 in the Master Router (45.8s) -- with 'Cannot read properties of
// undefined (reading \'message\')'. The ladder escalated correctly each time, so
// this was never a ladder bug: the model is dead, and every inbound message was
// paying ~45s for it before getting a real answer. That run took 87s end to end,
// and at 5 production slots this latency is a direct contributor to concurrency
// exhaustion -- the box hit 6/5 active with a growing queue the same morning.
//
// 30 Aug 2026: groqModel changed from 'llama-3.3-70b-versatile' to
// 'openai/gpt-oss-120b' on every tier. Groq SHUT DOWN llama-3.3-70b-versatile
// for free and developer tiers on 16 Aug 2026 -- their deprecations page names
// openai/gpt-oss-120b as the replacement, their models page now marks the old
// id Enterprise/Contact-Sales, and it has no row at all in the free-tier
// rate-limit table. Because Groq is only the FALLBACK model, it had never
// fired in production, so nothing had surfaced this: the slot would have
// failed for the first time on the day the primary was already down. The
// replacement is production-tier (not preview), free-tier callable, and
// supports OpenAI-style tool calling, which the ladder requires.
// Free-tier ceiling to remember: 30 RPM / 1K RPD / 8K TPM / 200K TPD -- the
// 8K tokens-per-minute limit binds well before the request limit does.
const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',                groqModel: GROQ_FALLBACK }
];
// 'Log Incoming Message' is a Supabase insert that returns an EMPTY body, so
// $input here carries no message and the Agent failed with "No prompt specified"
// on every tier -- which looked like a model outage but never was. Pull the
// conversation context straight from 'Resolve Lead Identity' and re-attach it on
// every retry, so the prompt survives the ladder loop.
let ctx = {};
try { ctx = $('Resolve Lead Identity').first().json || {}; } catch (e) { ctx = {}; }

const prev = $input.first().json;
const attempt = Number(prev.__attempt ?? -1) + 1;
if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed. Tried: ' + TIERS.map(t=>t.orModel).join(', '));
}
if (!ctx.message) {
  throw new Error('No message found on Resolve Lead Identity output - cannot prompt the agent.');
}
return [{ json: { ...ctx, ...prev, message: ctx.message, __attempt: attempt, orModel: TIERS[attempt].orModel, groqModel: TIERS[attempt].groqModel } }];

// Quality gate before anything reaches a real customer on WhatsApp.
//
// 31 Aug 2026 -- REWRITTEN after the worst leak this system has produced.
// A customer asked "can you do better for a cash payment?" and received the
// model's entire internal deliberation, roughly 3,000 characters of it,
// including the literal line "price_aed 585,000, cost_aed 530,000" -- what the
// dealership PAID for the car -- plus the 8% ceiling, the floor arithmetic, and
// long verbatim quotes of the negotiation rules themselves.
//
// The old gate matched a whitelist of opening phrases anchored with ^ :
//   /^(the user|okay|we need to|i should|let's see|analysis|reasoning)\b/
// The leak began "We have inventory data:" -- not on the list -- so it passed
// untouched. A whitelist of first words cannot work: there is an unbounded
// number of ways a model can start thinking out loud, and being wrong once
// costs the negotiation and the cost price.
//
// This gate is now DENY-based and looks at the WHOLE text, not the first word.
// Three independent tests, any one of which blocks:
//   1. Internal vocabulary that must never leave the building.
//   2. Meta-language -- the model talking ABOUT the reply instead of writing it.
//   3. A discount percentage, which the rules forbid quoting in any form.
// Blocking is deliberately biased toward false positives: a customer who gets
// one holding sentence has a mildly worse minute, while a customer who learns
// cost_aed has the whole negotiation.
const prev = $input.first().json;
let text = String(prev.output ?? '').trim();

// Explicit reasoning wrappers some models emit.
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '')
           .replace(/<reasoning>[\s\S]*?<\/reasoning>/gi, '')
           .replace(/<\|?(?:begin|start)_of_thought\|?>[\s\S]*?<\|?(?:end)_of_thought\|?>/gi, '')
           .trim();

// WhatsApp renders none of markdown. Convert what the model still slips through.
text = text.replace(/^\s*\|.*\|\s*$/gm, '')          // table rows
           .replace(/^\s*[-: |]{6,}\s*$/gm, '')      // table separators
           .replace(/\*\*(.+?)\*\*/g, '*$1*')        // **bold** -> *bold*
           .replace(/^#{1,6}\s*/gm, '')              // headings
           .replace(/\n{3,}/g, '\n\n')
           .trim();

const reasons = [];

// -- 1. Internal vocabulary -------------------------------------------------
// Database column names, tool names, workflow nouns and the headings of the
// agent's own rulebook. None of these has any business in a sales message, so
// a single occurrence anywhere is disqualifying. cost_aed leads the list
// because it is the one that costs real money.
const INTERNAL = [
  'cost_aed', 'price_aed', 'days_in_stock', 'ai_score', 'budget_aed',
  'lead_email', 'assigned_to', 'whatsapp.lead', 'vehicle_interest',
  'finance_calculator', 'search_inventory', 'search_policy', 'fromai',
  'system_note', 'initial_outreach', 'delivery report', 'audit_log',
  'communication_logs', 'system prompt', 'system message', 'guardrail',
  'negotiation guardrails', 'cash versus finance', 'no recaps',
  'whatsapp formatting', 'tool call', 'inventory data', 'inventory price'
];
const lower = text.toLowerCase();
for (const t of INTERNAL) {
  if (lower.includes(t)) { reasons.push('internal term: ' + t); break; }
}

// 31 Aug 2026: a leak reached a real customer reading
//   "We have inventory price 585,000. Customer credit score 600.
//    Finance calculator returned indicative APR 8.2-9.64"
// and NOTHING above caught it, because the list stores 'finance_calculator'
// with an underscore and the model wrote 'Finance calculator' with a space.
// A deny-list that only matches one spelling of a token is not a deny-list.
// So: match a second time against text whose separators are normalised, using
// only the tokens whose spaced form is still unambiguous in a sales message.
// ('search inventory' and 'assigned to' are deliberately NOT here -- a real
// salesperson could plausibly write both.)
// NOTE: 'price aed' / 'cost aed' are deliberately absent. Normalising
// price_aed to 'price aed' also matches the perfectly good sales line
// "Price AED 585,000." -- the test suite caught that regression. Column
// names built on _aed are handled by COLUMN_RE below, which accepts an
// underscore or a hyphen but never a space.
const INTERNAL_NORM = [
  'days in stock', 'ai score', 'lead email', 'vehicle interest',
  'finance calculator', 'system note', 'initial outreach', 'audit log',
  'communication logs', 'inventory price', 'inventory data',
  'inventory row', 'inventory record'
];
const COLUMN_RE = [
  /\b(?:cost|price|budget|value|margin)[_-]aed\b/i,
  /\bai[_-]score\b/i, /\bdays[_-]in[_-]stock\b/i,
  /\blead[_-]email\b/i, /\bassigned[_-]to\b/i, /\bvehicle[_-]interest\b/i,
  /\bgross[_-]margin\b/i, /\bnet[_-]margin\b/i, /\bholding[_-]cost\b/i
];
for (const re of COLUMN_RE) {
  if (re.test(text)) { reasons.push('column name: ' + re.source.slice(0, 32)); break; }
}
const norm = lower.replace(/[_\-]+/g, ' ').replace(/\s+/g, ' ');
for (const t of INTERNAL_NORM) {
  if (norm.includes(t)) { reasons.push('internal term (normalised): ' + t); break; }
}

// -- 1c. Structural internal identifiers -------------------------------------
// 02 Sep 2026. The deny-list above enumerates the columns we knew about. A
// live probe of the schema found eleven more that sailed straight through:
// vehicle_value_aed, loan_payoff_aed, equity_aed, finance_tier, credit_score,
// response_time_minutes, bitrix_lead_id, confidence_score, storage_path,
// apr_source, ltv_policy_source -- plus the view name v_inventory_sales.
// Enumerating columns is a losing race against a schema that keeps growing.
// The structural fact is stronger than any list: snake_case is a machine
// spelling. No human writes "your credit_score is 900" to a customer on
// WhatsApp, in any language this dealership sells in. So block the SHAPE.
// Emails, URLs and filenames are stripped first -- those legitimately carry
// underscores and must not trip the rule.
const deIdentified = text
  .replace(/\b[\w.+-]+@[\w.-]+\.\w{2,}\b/g, ' ')
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(/\b[\w-]+\.(?:jpe?g|png|gif|pdf|docx?|xlsx?|csv|txt)\b/gi, ' ');
const SNAKE_RE = /\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b/i;
const snakeHit = deIdentified.match(SNAKE_RE);
if (snakeHit) reasons.push('internal identifier (snake_case): ' + snakeHit[0].slice(0, 40));

// -- 1d. Internal commercial language ----------------------------------------
// The cost/margin test in 3b needs a money figure nearby. These phrasings carry
// no number and so escaped it, while still handing the customer the inside of
// the negotiation: "Our margin here is healthy", "I am allowed up to eight
// percent", "I cannot go below our floor". Margin, floor, ceiling and discount
// authority are internal concepts; a customer hears only a price.
// Scoped tightly with a possessive so ordinary car words survive: "showroom
// floor", "floor mats", "under the ceiling lining" and "cost of ownership"
// must all still send. (An unpossessed "under the ceiling" rule was tried and
// removed: it blocked a legitimate sunroof/headroom reply in the test suite.)
const INTERNAL_COMMERCIAL = [
  /\b(?:our|my|the)\s+(?:gross\s+|net\s+|profit\s+)?margin\b/i,
  /\b(?:our|my)\s+(?:price\s+)?(?:floor|ceiling)\b/i,
  /\b(?:below|under|beneath)\s+(?:our|my)\s+(?:floor|ceiling|cost|minimum)\b/i,
  /\bmax(?:imum)?\s+discount\b/i,
  /\bdiscount\s+(?:ceiling|ladder|authority|band|cap)\b/i,
  /\bi(?:'m|’m| am)\s+(?:allowed|authoris\w+|authoriz\w+|permitted)\s+(?:to\s+|up\s+to\s+)/i,
  /\bwhat\s+we\s+paid\b/i
];
for (const re of INTERNAL_COMMERCIAL) {
  if (re.test(text)) { reasons.push('internal commercial language: ' + re.source.slice(0, 40)); break; }
}

// -- 2. Meta-language -------------------------------------------------------
// The model narrating its own decision rather than talking to the customer.
// Phrases chosen to be things a salesperson would never write to a buyer.
// Note what is deliberately NOT here: "we can offer", "we can do" and similar
// are exactly how a real offer is phrased, so they must stay allowed.
const META = [
  /\bthe customer (?:asks|asked|is asking|wants|says)\b/i,
  /\bthe user\b/i,
  /\bwe (?:need to|must not|must ensure|should (?:not )?(?:say|offer|reveal|mention))\b/i,
  /\b(?:the|per the|according to the) (?:rule|rules|guideline|guidelines|policy states)\b/i,
  /\bthus we\b/i, /\bso we (?:need|must|can(?:not)?)\b/i,
  /\blet'?s (?:see|think|say)\b/i,
  /\bmust not (?:reveal|quote|say|mention)\b/i,
  /\bis (?:prohibited|disqualifying|forbidden)\b/i,
  /\bthat'?s okay\b/i, /\bbut we (?:need|must|haven'?t|don'?t)\b/i,
  /^(?:okay|alright)[,.]?\s+(?:the|so|we)\b/i,
  /\banalysis\s*:/i, /\breasoning\s*:/i,
  // 31 Aug 2026 -- added after the leak quoted above got through.
  // Talking ABOUT the customer in the third person. A reply written TO them
  // says "your credit score"; only a narration says "customer credit score".
  /\bcustomer(?:'s)?\s+(?:credit score|credit band|score|budget|email|phone number|intent|profile|message|reply)\b/i,
  // Naming the thing that produced a number instead of just giving the number.
  /\b(?:calculator|tool|search|lookup|query|system|api)\s+returned\b/i,
  /\breturned\s+(?:indicative|the following|a value|apr|results?)\b/i,
  // Opening by reciting retrieved data.
  /^\s*we have\s+(?:inventory|stock data|the data|data)\b/i
];
for (const re of META) {
  if (re.test(text)) { reasons.push('meta-language: ' + re.source.slice(0, 40)); break; }
}

// -- 3. Discount percentages ------------------------------------------------
// "NEVER write the discount percentage to the customer" -- quote money only.
// An APR is a legitimate percentage and must survive, so the test requires a
// discount word near the number rather than blocking every % sign.
const PCT_NEAR_DISCOUNT =
  /(\d{1,2}(?:\.\d+)?\s*%[^.\n]{0,60}\b(?:discount|off|off the list|reduction|below list)\b)|(\b(?:discount|off the list|reduction)\b[^.\n]{0,60}\d{1,2}(?:\.\d+)?\s*%)/i;
if (PCT_NEAR_DISCOUNT.test(text)) reasons.push('discount percentage quoted');
// 02 Sep 2026: the numeric test above only sees digits. "eight percent off"
// is the same disclosure written in words, so mirror it for spelled numbers.
const WORDNUM = '(?:one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty)';
const PCT_WORD_NEAR_DISCOUNT = new RegExp(
  '\\b' + WORDNUM + '\\s*(?:%|per\\s?cent|percent)\\b[^.\\n]{0,60}\\b(?:discount|off|below list|reduction)\\b' +
  '|\\b(?:discount|off the list|reduction)\\b[^.\\n]{0,60}\\b' + WORDNUM + '\\s*(?:%|per\\s?cent|percent)\\b', 'i');
if (PCT_WORD_NEAR_DISCOUNT.test(text)) reasons.push('discount percentage quoted (in words)');

// -- 3b. Cost and margin talk, however it is phrased -------------------------
// The token deny-list above catches the literal column names. It does NOT catch
// a model that paraphrases: "our internal acquisition cost is AED 530,000"
// contains no banned token and would have passed. Layer 1 now keeps these
// numbers out of the model's context entirely (the agent reads
// v_inventory_sales, which has no cost or margin columns), but this gate must
// still hold if that boundary is ever widened by accident.
// A money figure NEAR any cost/margin word is the signal -- not the word alone,
// because "at no cost to you" and "cost of ownership" are things a salesperson
// legitimately says.
const MONEY = /(?:aed|dhs?|د\.إ)\s?[\d,]{4,}|[\d,]{5,}\s?(?:aed|dhs?)/i;
const COST_WORD = /\b(?:acquisition cost|cost price|our cost|internal cost|we paid|we bought|purchase(?:d)? (?:it|the car|this) for|gross margin|net margin|our margin|markup|mark-up|our profit|profit margin|holding cost|commission)\b/i;
if (MONEY.test(text) && COST_WORD.test(text)) reasons.push('money figure next to a cost/margin word');

// -- 4. Shape ---------------------------------------------------------------
// A WhatsApp sales reply is short. Something this long is almost always the
// model thinking rather than answering, and the length itself is the tell.
if (text.length > 1500) reasons.push('too long for a WhatsApp reply: ' + text.length + ' chars');
if (text.length < 12)   reasons.push('too short / empty');

// -- 5. OUTBOUND FINANCE GATE (system Layer 4) ------------------------------
// 31 Aug 2026. A live customer was told "the indicative monthly payment over
// 60 months (with salary transfer) works out to roughly AED 11,200 per month".
// finance_calculator was never called. The model amortised the FULL AED 585,000
// -- 100% financing, which no UAE bank writes. The true figure was ~AED 7,800.
// Nothing caught it: no error, no failed node, no guard reason, audit SUCCESS.
//
// The system prompt already said "NEVER invent a rate, a tenure, a down payment
// or an approval." It said it clearly and the model ignored it. A prompt is not
// a control. Telling a model not to calculate is not the same as making it
// impossible for the calculation to reach a customer.
//
// The principle this layer enforces:
//   The AI may EXPLAIN an authoritative finance result.
//   The AI is NEVER the authority for a finance calculation.
//
// So: if the outgoing message asserts a finance figure, there must be evidence
// that finance_calculator actually ran IN THIS TURN and actually produced the
// class of figure being asserted. No evidence -> block. And crucially, a run
// that returned an APR but no instalment does NOT authorise an instalment --
// that is the exact shape of the incident and the whole point of the layer.
//
// Deliberately NOT blocked: the car's own price, a cash discount offer, a plain
// availability line. Those are the dealership's own numbers, not the bank's.

// -- 5a. Position helpers ----------------------------------------------------
// Proximity is computed on match POSITIONS rather than with one giant lookaround
// regex, so each figure class stays readable and auditable on its own.
function finPositions(re, s) {
  const out = [];
  const r = new RegExp(re.source, re.flags.indexOf('g') === -1 ? re.flags + 'g' : re.flags);
  let m;
  while ((m = r.exec(s)) !== null) {
    out.push([m.index, m.index + m[0].length]);
    if (m[0].length === 0) r.lastIndex++;
    if (out.length > 200) break;
  }
  return out;
}
// True when any A match sits within `span` characters of any B match, either
// side. Overlaps give a negative gap and therefore also count.
function finNear(A, B, span) {
  for (let i = 0; i < A.length; i++) {
    for (let j = 0; j < B.length; j++) {
      const a = A[i], b = B[j];
      const gap = a[0] < b[0] ? b[0] - a[1] : a[0] - b[1];
      if (gap <= span) return true;
    }
  }
  return false;
}

// -- 5b. What counts as money -----------------------------------------------
// Either a currency-tagged number, or a thousands-GROUPED number. A bare
// ungrouped run of digits only counts at 5+ digits, which keeps model years
// ("Lexus LX 600 2024") and tenures ("60 months") out of the money set --
// a 2024 read as money would have made the availability line unsendable.
// Group separators include a plain space because the live incident wrote
// "AED 585 000" and "AED 11 200" with spaces, not commas.
const FIN_MONEY_RE = /(?:aed|dhs?|dirhams?|د\.إ)\s*\d[\d.,   ]*\d|\d[\d.,   ]*\d\s*(?:aed|dhs?|dirhams?)\b|\b\d{1,3}(?:[,   ]\d{3})+\b|\b\d{5,}\b/gi;
const FIN_PCT_RE = /\d{1,3}(?:\.\d+)?\s*(?:%|per\s?cent\b|percent\b)/gi;

// Keyword sets, one per figure class.
// Two of these classes have a STRONG and a WEAK half, because the obvious
// keyword list over-blocks ordinary sales lines. The probes that forced the
// split, all of which must send:
//   "The price is AED 585,000 and delivery is in two months."
//   "We have had this one for a few months. Price AED 585,000."
//   "I can hold it with a small deposit and the price stays AED 585,000."
// A bare "months" is a duration; only "monthly", "per month", "EMI", "kist"
// and friends are inherently about a payment. Likewise a bare "deposit" sitting
// in the same sentence as the car's price is not a down-payment quote.

// STRONG monthly words -- these alone make a nearby money figure an instalment.
const FIN_MONTH_KW  = /(?:\bmonthly\b|per\s?month\b|a\s+month\b|\bemi\b|\binstal\w*|\bmahina\b|\bmahine\b|\bkist\w*|\bqist\w*|p\s?\/\s?m\b|\/mo\b|\/month\b)/gi;
// WEAK: a bare "month(s)". Counts only when a payment word is also close by.
const FIN_MONTH_WEAK_KW = /\bmonths?\b/gi;
const FIN_PAY_KW    = /(?:\bpay(?:ment|ments|able|ing)?\b|\brepay\w*|\bfinanc\w*|\bloan\b|\btenure\b|\bterm\b|\binstal\w*|\bemi\b)/gi;

const FIN_APR_KW    = /(?:\bapr\b|\binterest\b|\brates?\b|\breducing\b|\bflat\s+rate\b|\bprofit\s+rate\b)/gi;

// STRONG down-payment words.
const FIN_DOWN_KW   = /(?:\bdown[\s-]?payment\b|\bdownpayment\b)/gi;
// WEAK: "deposit" / "advance" are ordinary sales words, so the money has to be
// grammatically attached ("a deposit of AED 20,000"), not merely in the sentence.
const FIN_DOWN_WEAK_KW = /(?:\badvance\b|\bdeposit\b)/gi;

const FIN_TENURE_KW = /(?:\bover\s+\d{1,3}\s*months?\b|\b\d{1,3}\s*[-–]\s*month\b|\b\d{1,3}\s+months?\b)/gi;

const finMoney  = finPositions(FIN_MONEY_RE, text);
const finPct    = finPositions(FIN_PCT_RE, text);

// Spans are short on purpose. 40 chars is about a clause; a money figure and a
// payment word that far apart are almost always the same assertion.
const claims = [];
{
  // A weak "months" is promoted to a monthly keyword only when a payment word
  // sits within 30 chars of it -- "over 60 months of payments" yes,
  // "delivery is in two months" no.
  const pay = finPositions(FIN_PAY_KW, text);
  let mk = finPositions(FIN_MONTH_KW, text);
  if (pay.length) {
    for (const w of finPositions(FIN_MONTH_WEAK_KW, text)) if (finNear([w], pay, 30)) mk.push(w);
  }
  if (finMoney.length && mk.length && finNear(finMoney, mk, 40)) claims.push('monthly_payment');
}
if (finPct.length && finNear(finPct, finPositions(FIN_APR_KW, text), 40)) claims.push('apr');
{
  const dn = finPositions(FIN_DOWN_KW, text);
  const dw = finPositions(FIN_DOWN_WEAK_KW, text);
  const strong = dn.length && (finNear(finMoney, dn, 40) || finNear(finPct, dn, 40));
  const weak   = dw.length && (finNear(finMoney, dw, 18) || finNear(finPct, dw, 18));
  if (strong || weak) claims.push('down_payment');
}
// A tenure is only a finance assertion when money is attached to it AND a
// payment word is in play. "Delivery takes about two months" carries no figure,
// and "price AED 585,000, delivery is in 2 months" is a delivery date sitting
// near a car price -- neither is a repayment claim.
{
  const tn = finPositions(FIN_TENURE_KW, text);
  const pay2 = finPositions(FIN_PAY_KW, text);
  if (finMoney.length && tn.length && pay2.length &&
      finNear(finMoney, tn, 60) && finNear(tn, pay2, 40)) claims.push('tenure');
}

// -- 5c. Evidence ------------------------------------------------------------
// Read defensively and never throw. $('finance_calculator') THROWS when that
// node did not run in this execution -- it does not return undefined -- and in
// a plain Code-node context `$` may not exist at all. Both land in the catch.
let ev = {};
try { ev = $('finance_calculator').last().json || {}; } catch (e) { ev = {}; }

// The agent may also carry the result forward on the item itself. Only a
// whitelist of fields is honoured, so a model cannot mint evidence by writing
// arbitrary keys into its own output.
const EV_CARRY = ['finance_calculation_id', 'finance_execution_id', 'calculation_id',
                  'execution_id', 'emi_available', 'quotable', 'monthly_payment_low_aed',
                  'monthly_payment_high_aed', 'indicative_apr_low_pct', 'indicative_apr_high_pct',
                  'down_payment_aed', 'tenure_months', 'calculated_at', 'status'];
const carried = {};
for (const k of EV_CARRY) if (prev && prev[k] !== undefined && prev[k] !== null) carried[k] = prev[k];
ev = Object.assign({}, carried, ev);

function evHas(k) { return ev[k] !== undefined && ev[k] !== null && ev[k] !== ''; }

// An identifier is what proves a RUN happened, as opposed to a number the model
// simply typed. calculated_at counts: finance_calculator stamps it per run.
const EV_ID_KEYS = ['finance_calculation_id', 'finance_execution_id', 'calculation_id',
                    'execution_id', 'calculated_at', 'calculatedAt'];
let evHasId = false;
for (const k of EV_ID_KEYS) if (evHas(k)) { evHasId = true; break; }

// A failed or non-quotable run authorises nothing at all.
const evStatus = String(ev.status || '').toLowerCase();
const evUsable = evHasId && evStatus !== 'error' && evStatus !== 'input_error';
const evQuotable = ev.quotable !== false;
// emi_available === false is an explicit statement that NO instalment exists.
// It vetoes a monthly claim even if some stale monthly number is lying around.
const evEmiOk = ev.emi_available !== false;

// The discrimination that matters: each class needs ITS OWN figure present.
function authorised(cls) {
  if (!evUsable) return false;
  if (cls === 'monthly_payment') return evQuotable && evEmiOk && evHas('monthly_payment_low_aed');
  if (cls === 'apr')             return evQuotable && evHas('indicative_apr_low_pct');
  if (cls === 'down_payment')    return evHas('down_payment_aed');
  // A money-bearing tenure claim is an instalment claim in other words, so it
  // is satisfied by an instalment or by an explicit tenure from the calculator.
  if (cls === 'tenure')          return evQuotable && evEmiOk &&
                                        (evHas('monthly_payment_low_aed') || evHas('tenure_months'));
  return false;
}

const financeClaimDetected = claims.length > 0;
const unauthorised = [];
for (const c of claims) if (!authorised(c)) unauthorised.push(c);
const financeEvidenceOk = financeClaimDetected ? unauthorised.length === 0 : true;

// Reasons from layers 1-4 decide which fallback the customer sees, so capture
// the count BEFORE this layer adds its own.
const preFinanceReasonCount = reasons.length;
for (const c of unauthorised) reasons.push('finance figure without calculator evidence: ' + c);

// -- Fallbacks ---------------------------------------------------------------
const FALLBACK = "Sorry, that didn't come out right on my side. Let me get you a proper answer - one moment.";
// A finance block is not a malfunction the customer should feel. It is a
// promise of a real number instead of a guessed one, and it keeps the thread
// alive rather than ending on an apology.
const FINANCE_FALLBACK = "Let me get you the exact monthly figure from our finance desk rather than guess - one moment. Meanwhile, is there anything else about the car I can answer?";

const blocked = reasons.length > 0;
const safe = blocked
  ? (preFinanceReasonCount > 0 ? FALLBACK : FINANCE_FALLBACK)
  : text;

return [{ json: {
  ...prev,
  output: safe,
  guard_blocked: blocked,
  guard_reasons: reasons,
  raw_output: text,
  finance_claim_detected: financeClaimDetected,
  finance_evidence_ok: financeEvidenceOk,
  finance_claim_classes: claims
} }];

// Stop a second INITIAL_OUTREACH to a lead we already messaged in the last 24h.
// On 16 Aug the router was posted twice and the customer got two near-identical
// welcome messages 4 minutes apart. Inbound replies are never blocked - only
// proactive outreach.
const ctx = $('Resolve Lead Identity').first().json;
const isOutreach = ctx.direction === 'outbound' ||
                   String(ctx.message || '').startsWith('INITIAL_OUTREACH:');

if (!isOutreach) return [{ json: ctx }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
if (rows.length > 0) {
  // Already contacted recently -> return nothing, which halts this branch.
  return [];
}
return [{ json: ctx }];

// This workflow runs with binaryMode "separate", so n8n keeps binary payloads
// on disk and binary.data.data is a REFERENCE, not base64. Reading it directly
// sent garbage to the vision model ("Bad request - Provider returned error").
// getBinaryDataBuffer() is the only way that works in both binary modes.
const ctx = $('Resolve Lead Identity').first().json;
const bin = ($input.first().binary || {}).data;
if (!bin) {
  throw new Error('KYC image download produced no binary property - check the WAHA file URL and API key.');
}
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buf.toString('base64');
if (!b64 || b64.length < 100) {
  throw new Error('KYC image decoded to ' + b64.length + ' base64 chars - too small to be a document.');
}
return [{ json: {
  document_base64: b64,
  mime_type: bin.mimeType || 'image/jpeg',
  size_bytes: buf.length,
  chat_id: ctx.sender,
  lead_email: ctx.lead_email,
  lead_name: ctx.lead_name,
  // 2 Sep 2026: the KYC auditor writes kyc_documents rows. Without this it
  // would write them under whichever tenant holds is_unattributed_default,
  // i.e. a second dealership's Emirates ID would land in the first
  // dealership's compliance screen.
  tenant_id: ctx.tenant_id || null
} }];

// Every node whose success this run is about to claim.
const CLAIMED = [
  { node: 'Send Reply via WAHA HTTP API', what: 'WhatsApp reply to the customer', critical: true },
  { node: 'Log Conversation',             what: 'communication_logs row for the reply', critical: false },
  { node: 'Claim Message Id',             what: 'idempotency claim in processed_messages', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

// 30 Aug 2026: a voice note adds a FOURTH, non-critical claim -- but only on
// runs where the voice branch actually ran. Adding it to CLAIMED unconditionally
// would make check() report 'node did not run on this branch' for every text
// message and turn every text run PARTIAL.
let voiceClaim = null;
try {
  const mt = $('Merge Voice Transcript');
  if (mt && (mt.isExecuted === undefined || mt.isExecuted)) {
    const v = mt.first().json || {};
    voiceClaim = {
      what: 'voice note transcription',
      critical: false,
      ok: v.voice_transcribed === true,
      why: v.voice_transcribed === true ? '' : String(v.voice_drop_reason || 'transcription failed').slice(0, 300),
    };
  }
} catch (e) { voiceClaim = null; }

// 02 Sep 2026: Guard Reply substitutes a holding sentence when it blocks, so
// the customer never sees the leak -- but until now NOTHING recorded that a
// block had happened. The run wrote SUCCESS, the audit row said 'all 3 claimed
// steps verified', and no human ever learned that a real answer was suppressed.
// A suppressed reply is a customer left waiting on something the bot could not
// safely say, which is precisely the case a human must pick up. Report it
// through the Delivery Report -> audit_log path this workflow already uses,
// rather than adding a second escalation channel.
// Non-critical on purpose: the customer DID receive the holding sentence, so
// the run is PARTIAL (needs a human), not FAILED (delivery broke).
let guardClaim = null;
try {
  const g = $('Guard Reply').first().json || {};
  if (g.guard_blocked === true) {
    guardClaim = {
      what: 'AI reply suppressed by Guard Reply - NEEDS HUMAN FOLLOW-UP',
      critical: false,
      ok: false,
      why: (Array.isArray(g.guard_reasons) ? g.guard_reasons.join('; ') : String(g.guard_reasons || 'blocked')).slice(0, 300),
    };
  }
} catch (e) { guardClaim = null; }

const results  = CLAIMED.map(check);
if (voiceClaim) results.push(voiceClaim);
if (guardClaim) results.push(guardClaim);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
}, pairedItem: { item: 0 } }];

// Make.com used to do this: take a raw inbound enquiry and hand the Master
// Router a lead-shaped object. Make.com is empty now -- every workflow was
// moved into n8n -- so WhatsApp is the live inbound channel and this is where
// the shaping happens.
//
// `Validate & Enrich Input` on the Router accepts `.body`, `.lead`, or a bare
// object, and needs an email OR a phone. We have the phone.
const ctx = $('Resolve Lead Identity').first().json;

const digits = String(ctx.sender_phone || '').replace(/[^0-9]/g, '');
if (!digits) return [];   // nothing the Router could key a lead on

return [{ json: {
  name: ctx.lead_name || ctx.push_name || 'WhatsApp enquiry',
  phone: '+' + digits,
  email: ctx.lead_email || null,
  message: ctx.message || null,
  vehicle_interest: ctx.message || null,
  source: 'whatsapp',
  // 2 Sep 2026: the Router CREATES the lead row. The tenant has to travel with
  // the lead or the Router files a second dealership's customer inside the
  // first dealership's tenant -- the exact failure this whole pass is about.
  tenant_id: ctx.tenant_id || null,
  // Tells the Router the customer is ALREADY in a live thread, so it scores,
  // alerts and syncs but does NOT fire a canned welcome on top of the reply
  // the BDC agent has just sent them.
  origin: 'whatsapp-bdc',
} }];

// Human Spoke Recently?  — added by the human-handover handoff.
//
// Collapses `Human Reply Check` (0 or 1 row, or 1 error item) into EXACTLY ONE
// item carrying the Resolve Lead Identity context plus a mode. Every node after
// this one runs once per item, so returning anything other than one item would
// multiply the whole reply chain.
//
// THE TWO WINDOWS. Both live here and nowhere else.
//   HARD_SILENCE_MIN  30  — a rep spoke within the last 30 minutes: the bot says
//                           NOTHING. A WhatsApp haggle runs at minutes per turn,
//                           and the failure this fixes ("I can do 78,000 final"
//                           / "ok" / bot quotes its own number) happens inside
//                           one of those turns. 30 minutes also covers the rep
//                           putting the phone down to walk the lot. It does not
//                           strand the customer: by definition a person is on
//                           this thread right now.
//   SUPERVISED_HOURS  12  — from 30 minutes to 12 hours the bot DOES answer,
//                           instantly, but its prompt is told a colleague is
//                           already in this conversation and it must not touch
//                           any number that colleague named. A customer who
//                           writes the next morning is past 12h and gets normal
//                           service; a customer who writes at midnight after a
//                           7pm rep message still gets an instant answer, just a
//                           careful one. Full silence for 12h would be the cure
//                           killing the patient.
//
// FAIL DIRECTION. If the lookup could not be done (Supabase down, malformed
// or=() filter, PostgREST 400) we do NOT know whether a rep is mid-negotiation.
// That degrades to 'supervised', not to 'normal': the customer still gets an
// instant reply, but one that cannot contradict a colleague. Zero rows is a real
// answer, not an error, and gives 'normal'.
const HARD_SILENCE_MIN = 30;
const SUPERVISED_HOURS = 12;

let ctx = {};
try { ctx = $('Resolve Lead Identity').first().json || {}; } catch (e) { ctx = {}; }

const rows = $input.all().map(i => (i && i.json) || {});
const errored = rows.some(r => r.error !== undefined && r.error !== null);
const hit = rows.find(r => r && r.created_at);

let mode = 'normal';
let human_minutes = null;
let last_human_by = '';
let last_human_message = '';

if (hit) {
  const t = new Date(hit.created_at).getTime();
  if (isNaN(t)) {
    mode = 'supervised';
  } else {
    human_minutes = Math.max(0, Math.round((Date.now() - t) / 60000));
    last_human_by = String(hit.sent_by || 'a colleague');
    last_human_message = String(hit.message || '').replace(/\s+/g, ' ').trim().slice(0, 400);
    mode = human_minutes < HARD_SILENCE_MIN ? 'silent'
         : human_minutes < SUPERVISED_HOURS * 60 ? 'supervised'
         : 'normal';
  }
} else if (errored) {
  mode = 'supervised';
}

// The block the agent prompt prepends. Empty unless we are supervising.
let handover_note = '';
if (mode === 'supervised') {
  handover_note =
    'HANDOVER NOTE — READ THIS BEFORE ANSWERING. A human colleague from the dealership is already '
    + 'handling this conversation on this same WhatsApp number'
    + (human_minutes === null
        ? '.'
        : '; their last message to this customer was ' + human_minutes + ' minutes ago'
          + (last_human_message ? ' and it said: "' + last_human_message + '"' : '.'))
    + '\n'
    + 'Do NOT contradict your colleague. Do NOT restate, improve, reduce, re-confirm or withdraw any '
    + 'price, discount, figure, deadline or commitment they have made, and do NOT make a commercial '
    + 'offer of your own in this thread. Answer only the factual part of what the customer just asked '
    + '— stock, specification, availability, timing, policy. If they are asking about price, payment, '
    + 'discount, part-exchange value or anything already being negotiated, say your colleague is '
    + 'looking after that and will come straight back to them, and stop there. Keep it to one or two '
    + 'short lines and do not open a new topic.';
}

return [{ json: {
  ...ctx,
  human_mode: mode,
  human_minutes,
  last_human_by,
  last_human_message,
  handover: mode === 'supervised',
  handover_note,
  human_check_errored: errored
}, pairedItem: { item: 0 } }];

// Prepare Voice Upload
// Validates the WAHA download, applies the duration cap, and normalises the
// binary metadata so Groq accepts the multipart upload.
//
// Deliberately does NOT call this.helpers.getBinaryDataBuffer(): the workflow
// runs with binaryMode "separate", so the audio bytes live outside the item.
// Pulling them into the heap of a 958 MB box buys nothing -- only the binary
// METADATA is needed, and n8n streams the file itself at upload time.
const MAX_SECONDS = 180;

// Duration comes from `Extract Message & Sender`, which read it off
// payload._data.Message.audioMessage.seconds. No webhook reach-back is needed:
// the outreach entry path (`Called by Master Router`) never sets is_voice, so
// this node is unreachable from it.
let ex = {};
try { ex = $('Extract Message & Sender').first().json || {}; } catch (e) { ex = {}; }
const seconds = Number(ex.audio_seconds || 0);

const out = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const binary = item.binary || {};

  let ok = true;
  let reason = '';

  if (json.error !== undefined && json.error !== null) {
    // `Download Voice Note` runs with onError: continueRegularOutput, so a 404
    // after WHATSAPP_FILES_LIFETIME (180s) expiry lands here as data, not a throw.
    ok = false;
    reason = 'waha download failed: ' + String((json.error && (json.error.message || json.error.description)) || json.error).slice(0, 200);
  } else if (!binary.data) {
    ok = false;
    reason = 'waha returned no audio body (file expired, 404, or media was never stored)';
  } else if (seconds > MAX_SECONDS) {
    ok = false;
    reason = 'voice note is ' + seconds + 's, over the ' + MAX_SECONDS + 's cap';
  } else if (!String(binary.data.mimeType || ex.audio_mime || '').toLowerCase().startsWith('audio/')) {
    ok = false;
    reason = 'unsupported mimetype: ' + String(binary.data.mimeType || ex.audio_mime || 'unknown');
  }

  if (ok) {
    // Groq rejects an upload whose filename carries no recognised audio
    // extension. WAHA sets media.filename to null for audio, and n8n then falls
    // back to the URL basename or the literal "data". Force it.
    item.binary.data.fileName = 'voice.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }

  out.push({
    json: {
      voice_ok: ok,
      voice_drop_reason: reason,
      voice_seconds: seconds,
      voice_mime: String(ex.audio_mime || 'audio/ogg; codecs=opus'),
    },
    binary: ok ? item.binary : undefined,
    pairedItem: { item: 0 },
  });
}
return out;

// Merge Voice Transcript
// Single join point for both legs: Groq success/failure, and the give-up leg
// from `Voice Is Usable?` false. It NEVER throws and it always emits exactly
// one item, so the customer is never met with silence because of this branch.
const j = ($input.first() || {}).json || {};

// The Groq HTTP node REPLACES the item, so the pre-flight verdict has to be
// read back from `Prepare Voice Upload` explicitly.
let prep = {};
try { prep = $('Prepare Voice Upload').first().json || {}; } catch (e) { prep = {}; }

let transcript = '';
let language = null;
let reason = String(prep.voice_drop_reason || '');

if (!reason) {
  // We came through Groq.
  if (j.error !== undefined && j.error !== null) {
    reason = 'groq: ' + String((j.error && (j.error.message || j.error.description)) || j.error).slice(0, 200);
  } else {
    transcript = String(j.text ?? '').trim();
    language = j.language ? String(j.language) : null;
    if (!transcript) reason = 'groq returned an empty transcript';
  }
}

const ok = !reason && !!transcript;

// The fallback is an INSTRUCTION to the agent, not a canned string sent to the
// customer -- that is the only way the apology comes back in the customer's own
// language. Same convention as the INITIAL_OUTREACH: prefix that
// `Extract Message & Sender` already injects for router-initiated outreach.
//
// The drop reason is deliberately NOT interpolated into this text. It flows
// downstream into `Reply Eligibility`, whose 73-keyword allowlist is a substring
// match -- an arbitrary Groq error string could contain "model" or "service" and
// silently widen the allowlist for an unknown number.
const NOTE = 'SYSTEM_NOTE: This person sent a WhatsApp voice message and we were not able to turn it into text. Do not guess what they said. Reply briefly, in whatever language they have been writing in, say sorry you missed it, and ask them to write it out or send a shorter recording.';

return [{ json: {
  message: ok ? transcript : NOTE,
  is_voice: true,
  voice_transcribed: ok,
  voice_transcript: ok ? transcript : '',
  voice_language: language,
  voice_seconds: Number(prep.voice_seconds || 0),
  voice_drop_reason: ok ? '' : reason,
}, pairedItem: { item: 0 } }];

// WAHA Auth Gate
// -----------------------------------------------------------------------------
// Sits on the ONLY public path into this workflow: POST /webhook/whatsapp-inbound.
// Before this node existed, ANY caller on the internet who knew that URL could
// drive the whole chain below: make the dealership's own WhatsApp number send a
// message to any phone number it chose (`Send Reply via WAHA HTTP API` sends to
// `body.payload.from`, which is caller-supplied), burn OpenRouter and Groq
// credits, and write rows into communication_logs, whatsapp_contacts,
// processed_messages and leads.
//
// The other entry point, `Called by Master Router` (executeWorkflowTrigger ->
// Extract Message & Sender), does NOT pass through here and is unchanged.
//
// WHAT THIS DOES NOT DO: `WAHA Webhook (POST)` responds onReceived, so the HTTP
// 200 is already on the wire before this node runs. An unauthorised caller still
// gets a 200. What the gate buys is that NOTHING HAPPENS for that caller: no
// WhatsApp send, no model call, no database write. Do not describe it as
// returning 401. It is also why a misconfigured secret can never make WAHA think
// the endpoint is broken and back off -- WAHA keeps seeing 200 either way.
//
// THREE STATES, all driven by container env vars (the established $env pattern
// here; N8N_BLOCK_ENV_ACCESS_IN_NODE=false):
//
//   WAHA_WEBHOOK_SECRET unset/empty  -> DORMANT. Every item passes, exactly as
//                                        before this node existed. This is the
//                                        env-level rollback. THIS IS THE STATE
//                                        THE BOX IS IN UNTIL ALI SETS THE VAR,
//                                        AND IT IS NOT A SAFE RESTING STATE.
//   secret set, WAHA_WEBHOOK_ENFORCE != 'true'
//                                    -> MONITOR. Every item passes, tagged, so
//                                        you can confirm in the execution list
//                                        that WAHA is really sending the header
//                                        BEFORE you enforce.
//   secret set, WAHA_WEBHOOK_ENFORCE == 'true'
//                                    -> ENFORCE. Items without a matching header
//                                        are dropped (return [] -> nothing
//                                        downstream runs). No throw, so an
//                                        attacker generates no error-workflow
//                                        alert storm.
//
// 3 Sep 2026 -- TWO CHANGES, both about being able to SEE what state this is in.
//
// 1. `_gate` IS NOW EMITTED IN EVERY STATE, and carries `mode`.
//    The previous version returned the items untouched when dormant, so the way
//    to tell DORMANT from MONITOR was the ABSENCE of the `_gate` key. That is a
//    terrible signal: absence is also what you get from a node that did not run,
//    a node that was disabled, and an older published version. An audit on 3 Sep
//    had to run the workflow with a payload that dies before any write purely to
//    observe that absence. Read `_gate.mode` instead. `ok`, `header_present` and
//    `enforcing` are kept with their old meanings so nothing that reads them
//    breaks.
//
// 2. ENFORCE WITHOUT A SECRET NOW FAILS CLOSED.
//    Previously the dormant check came first, so `WAHA_WEBHOOK_ENFORCE=true`
//    with an empty/typo'd/commented-out `WAHA_WEBHOOK_SECRET` passed EVERYTHING
//    -- an operator who had explicitly asked for enforcement silently got an
//    open endpoint. That is the worst possible direction for a misconfiguration
//    to fail. It now drops everything instead. The failure is then loud in the
//    only way that matters commercially (the bot stops replying, Ali notices in
//    minutes) rather than silent and open.
//
// The `_gate` key it adds is inert: `Prefilter` is a Set node in assignments
// mode with includeOtherFields off, so it emits only its four assignments and
// _gate never reaches anything else. `Extract Message & Sender` reaches back
// with $('WAHA Webhook (POST)') by name, which is unaffected by this insertion.
//
// FASTEST ROLLBACK (no restart, no env change, ~10 seconds): open this workflow
// in the n8n editor, right-click this node, "Deactivate"/disable it, save. A
// disabled node passes its input straight through to its output, so the channel
// is instantly back to its pre-patch behaviour.
const EXPECTED = String($env.WAHA_WEBHOOK_SECRET || '');
const ENFORCE  = String($env.WAHA_WEBHOOK_ENFORCE || '').trim().toLowerCase() === 'true';
const HEADER   = 'x-nexus-webhook-secret';

const items = $input.all();

// MISCONFIGURED ENFORCE -> fail closed. See note 2 above. Nothing downstream
// runs; the saved execution shows this node emitting zero items, which is the
// evidence that the secret is missing rather than the header being wrong.
if (ENFORCE && !EXPECTED) {
  return [];
}

const MODE = !EXPECTED ? 'DORMANT' : (ENFORCE ? 'ENFORCE' : 'MONITOR');

// Length-independent-ish constant-time compare. Not a defence against a remote
// timing attack over the public internet (network jitter dwarfs it) -- it is
// here because comparing secrets with === is a habit worth not having.
function sameSecret(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const headers = (item.json && item.json.headers) || {};

  // Node lower-cases inbound header names, but do not rely on it.
  let got = '';
  for (const k of Object.keys(headers)) {
    if (String(k).toLowerCase() === HEADER) { got = String(headers[k] == null ? '' : headers[k]); break; }
  }

  const present = got !== '';
  const ok = present && !!EXPECTED && sameSecret(got, EXPECTED);

  // ENFORCE and not ok -> silently dropped. No throw, no log, no cost.
  if (MODE === 'ENFORCE' && !ok) continue;

  out.push({
    json: Object.assign({}, item.json, {
      _gate: { mode: MODE, ok: ok, header_present: present, enforcing: MODE === 'ENFORCE' }
    }),
    binary: item.binary,
    pairedItem: { item: i }
  });
}

return out;

// NEXUS - Resolve Tenant  (inbound WhatsApp)
// ---------------------------------------------------------------------------
// WHY THIS NODE EXISTS
// n8n talks to Supabase as service_role. service_role is BYPASSRLS and carries
// no auth.uid(), so every row n8n writes without an explicit tenant_id falls
// back to the column DEFAULT, public.nexus_default_tenant_id(), which for an
// unauthenticated writer resolves to whichever tenant holds
// tenants.is_unattributed_default. That is dealership ONE. A second
// dealership's customers would be created inside dealership one's tenant:
// visible to their staff, invisible to their own. No RLS policy can fix that -
// the row is genuinely stamped with the wrong owner. This node is where the
// guessing stops.
//
// THE SIGNAL, AND WHY IT IS STILL THE RIGHT ONE
// The WAHA session the message arrived on. One WAHA session == one WhatsApp
// Business number == one dealership. WAHA puts it on the webhook body as
// `session`. That IS the correct signal: it describes which of the dealership's
// own numbers the message landed on, which is exactly the question being asked.
// Deleting it and inventing something else would throw away the only real
// evidence in the request.
//
// 3 Sep 2026 -- WHAT WAS ACTUALLY WRONG WITH IT
// The signal was never the defect. The defect was that it was UNAUTHENTICATED
// and UNVALIDATED, and that a value which failed to validate was rescued by a
// default instead of refused:
//
//   unauthenticated -> anyone who could reach POST /webhook/whatsapp-inbound
//     could type any session they liked. That is closed by `WAHA Auth Gate`
//     upstream (a shared secret proving the sender really is WAHA), not here.
//     This node cannot fix it and should not pretend to.
//   unvalidated -> the old code accepted a session that was NOT in the map and
//     then fell through to `sole_configured_tenant`, i.e. dealership one. So an
//     unknown session did not fail; it landed in the live dealership's books.
//     With two dealerships configured the same JSON field would have chosen
//     between them. THAT is what is fixed here.
//
// THE RULE NOW: ALLOWLIST, AND REFUSE RATHER THAN DEFAULT.
// A session resolves a tenant if and only if it is a key of the map and maps to
// a UUID. Anything else -- unknown session, empty session, absent session,
// non-UUID value -- returns NO ITEMS. Nothing downstream runs: no message id is
// claimed, no contact upserted, no reply sent, no lead created, no audit row.
// There is deliberately no fallback and no default. `sole_configured_tenant` is
// gone from this path: "we only have one dealership so it must be theirs" is
// exactly the reasoning that turns an unidentified message into their customer.
//
// Note the two locks are independent and both are needed. The gate answers "is
// this really WAHA?". This node answers "which of our numbers did it arrive
// on?". A dormant gate does not make this node unsafe, and this node does not
// make a dormant gate safe.
//
// THE MAP
// $env.NEXUS_TENANT_MAP, a JSON object { "<waha session>": "<tenant uuid>" }.
// If it is unset or unparseable we fall back to BUILTIN below, whose single key
// `default` is the live WAHA session name on this box (confirmed: `Send Reply
// via WAHA HTTP API` posts session 'default', and the infra probe reads
// /api/sessions/default). Onboarding dealership two means adding its session
// here, in one place, and nothing else changes.
//
// LIVE-PATH RISK, STATED PLAINLY. The one way this change can hurt the live
// dealership is if WAHA on this box does not put `session` on the webhook body
// at all -- then every real customer message is refused. That has NOT been
// observed on this box (no real inbound message has run through a saved
// execution since 2 Sep, so there is no captured body to read), which is why
// the very first step of the rollout is Ali sending himself one WhatsApp and
// confirming a reply. If it breaks, the 10-second rollback is to disable THIS
// node in the editor: a disabled node passes its input straight through, and
// `Extract Message & Sender` then yields tenant_id null, which is precisely the
// pre-patch behaviour.
const BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let map = {};
try { map = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { map = {}; }
if (!map || typeof map !== 'object' || Array.isArray(map) || !Object.keys(map).length) map = BUILTIN;

// The webhook body is no longer on the item here: Prefilter is a Set node with
// includeOtherFields off, so it emits only its four assignments. Reach back to
// the trigger by name - the established pattern in this workflow.
let session = '';
try { session = String((($('WAHA Webhook (POST)').first().json || {}).body || {}).session || '').trim(); }
catch (e) { session = ''; }

// hasOwnProperty, not `in` and not map[session] directly: a caller-supplied
// session of 'constructor' or 'toString' must not reach an inherited member.
const claimed = (session && Object.prototype.hasOwnProperty.call(map, session))
  ? String(map[session] == null ? '' : map[session])
  : '';

if (!UUID.test(claimed)) {
  // FAIL CLOSED. No tenant, no run. The saved execution still shows the webhook
  // body, so the rejected session is visible in the execution list without this
  // node writing anything an unauthenticated caller could have caused.
  return [];
}

return $input.all().map((item, i) => ({
  json: Object.assign({}, item.json, {
    tenant_id: claimed,
    tenant_source: 'waha_session',
    waha_session: session
  }),
  binary: item.binary,
  pairedItem: { item: i }
}));
